-- ==================================================
-- BEGIN sql/24_leave_universe_transfer_ownership.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Départ d'un univers : transfert de propriété au owner
-- À exécuter dans Supabase Dashboard > SQL Editor > New query
-- (nécessite sql/18_universes_phase1.sql et sql/19_campaign_sharing.sql)
-- ══════════════════════════════════════════════════════════════
--
-- Quand un membre quitte un univers (de son plein gré, ou après avoir
-- été retiré par un owner/admin), tout ce qu'il y a créé (personnages,
-- chroniques, documents, couche de carte + marqueurs) est transféré
-- au propriétaire de l'univers au lieu de rester bloqué derrière un
-- compte qui n'y a plus accès. Les tags personnels liés sont nettoyés
-- comme lors d'un transfert d'objet classique (cf. transfer_item /
-- _cleanup_char_tags_on_transfer / _cleanup_doc_tags_on_transfer).
--
-- Remplace la suppression directe de universe_members côté client :
-- le frontend doit désormais appeler ce RPC plutôt que
-- `sb.from('universe_members').delete()...`.
-- ══════════════════════════════════════════════════════════════

CREATE OR REPLACE FUNCTION public.remove_universe_member(
  p_universe_id UUID,
  p_user_id     UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner_id        UUID;
  v_char_id         UUID;
  v_doc_id          UUID;
  v_map_key         TEXT;
  v_owner_has_layer BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner_id
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF p_user_id = v_owner_id THEN
    RAISE EXCEPTION 'Le propriétaire ne peut pas quitter son propre univers';
  END IF;

  IF auth.uid() <> p_user_id AND NOT public.has_universe_role(p_universe_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'Non autorisé';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.universe_members
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Cet utilisateur n''est pas membre de cet univers';
  END IF;

  -- ── Personnages ────────────────────────────────────────────
  FOR v_char_id IN
    SELECT id FROM public.characters
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    PERFORM public._cleanup_char_tags_on_transfer(v_char_id, p_user_id);
    UPDATE public.characters SET user_id = v_owner_id, updated_at = NOW() WHERE id = v_char_id;
  END LOOP;

  -- ── Chroniques (pas de système de tags) ───────────────────
  UPDATE public.chronicles
  SET user_id = v_owner_id, updated_at = NOW()
  WHERE universe_id = p_universe_id AND user_id = p_user_id;

  -- ── Documents ──────────────────────────────────────────────
  FOR v_doc_id IN
    SELECT id FROM public.documents
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    PERFORM public._cleanup_doc_tags_on_transfer(v_doc_id, p_user_id);
    UPDATE public.documents SET user_id = v_owner_id, updated_at = NOW() WHERE id = v_doc_id;
  END LOOP;

  -- ── Couches de carte + marqueurs ──────────────────────────
  -- map_layers a une contrainte UNIQUE(user_id, map_key) : si le
  -- propriétaire possède déjà une couche pour cette carte, on fusionne
  -- les marqueurs dans la sienne et on supprime la couche devenue vide
  -- plutôt que de réassigner (ce qui violerait la contrainte).
  FOR v_map_key IN
    SELECT DISTINCT map_key FROM public.map_layers
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    UPDATE public.map_markers
    SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;

    SELECT EXISTS (
      SELECT 1 FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = v_owner_id AND map_key = v_map_key
    ) INTO v_owner_has_layer;

    IF v_owner_has_layer THEN
      DELETE FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    ELSE
      UPDATE public.map_layers
      SET user_id = v_owner_id, updated_at = NOW()
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    END IF;
  END LOOP;

  -- ── Tags personnels devenus orphelins (aucun objet ne les utilise) ──
  DELETE FROM public.tags
  WHERE universe_id = p_universe_id AND user_id = p_user_id
    AND NOT EXISTS (
      SELECT 1 FROM public.character_tags ct
      JOIN public.characters c ON c.id = ct.character_id
      WHERE ct.tag_id = tags.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.followed_character_tags fct
      WHERE fct.tag_id = tags.id AND fct.user_id = p_user_id
    );

  DELETE FROM public.doc_tags
  WHERE universe_id = p_universe_id AND user_id = p_user_id
    AND NOT EXISTS (
      SELECT 1 FROM public.document_tags dt
      JOIN public.documents d ON d.id = dt.document_id
      WHERE dt.tag_id = doc_tags.id
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.followed_document_tags fdt
      WHERE fdt.tag_id = doc_tags.id AND fdt.user_id = p_user_id
    );

  -- ── Retrait de l'univers ───────────────────────────────────
  DELETE FROM public.universe_members
  WHERE universe_id = p_universe_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.remove_universe_member(UUID, UUID) TO authenticated;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • À appeler via sb.rpc('remove_universe_member', { p_universe_id, p_user_id })
--    aussi bien pour un départ volontaire (p_user_id = soi-même) que pour
--    un retrait par un owner/admin (p_user_id = la cible).
--  • Personnages / chroniques / documents / couches de carte + marqueurs
--    créés par le membre partant deviennent la propriété du owner.
--  • Les campagnes ne sont pas concernées : elles n'appartiennent déjà
--    qu'au owner (cf. sql/19_campaign_sharing.sql).
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/24_leave_universe_transfer_ownership.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/25_unify_tags.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Unification du système de tags
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- (jusqu'à sql/24_leave_universe_transfer_ownership.sql inclus).
--
-- Les tags redeviennent une organisation strictement personnelle :
-- un utilisateur pose ses tags sur n'importe quel personnage ou
-- document qu'il peut voir (les siens ou ceux d'un autre membre de
-- l'univers), indépendamment de qui possède l'objet. Il n'y a donc
-- plus lieu de distinguer "mes tags sur mes objets" (character_tags)
-- de "mes tags sur les objets des autres" (followed_character_tags) :
-- les deux sont fusionnés en une seule table par domaine.
--
-- Conséquence : plus aucun mécanisme ne copie les tags du créateur
-- d'un objet vers l'utilisateur qui le consulte (sync_owner_tags et
-- ses helpers sont supprimés — ils étaient de toute façon déjà
-- inertes côté frontend, et cassés depuis la suppression de
-- followed_characters/followed_documents dans sql/19_campaign_sharing.sql).
-- Un transfert de propriété (transfer_item, remove_universe_member)
-- ne touche donc plus aux tags : ce sont ceux de qui les a posés,
-- pas de qui possède l'objet.
--
-- Migration destructive : aucune donnée existante à préserver.
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Personnages : character_tags + followed_character_tags → character_tags ──

DROP TABLE IF EXISTS public.character_tags CASCADE;
ALTER TABLE public.followed_character_tags RENAME TO character_tags;
ALTER TABLE public.character_tags DROP COLUMN IF EXISTS id;

ALTER TABLE public.character_tags DROP CONSTRAINT IF EXISTS followed_character_tags_pkey;
ALTER TABLE public.character_tags
  ADD CONSTRAINT character_tags_pkey PRIMARY KEY (universe_id, user_id, character_id, tag_id);

DROP INDEX IF EXISTS public.idx_followed_character_tags_user;
DROP INDEX IF EXISTS public.idx_followed_character_tags_character;
DROP INDEX IF EXISTS public.followed_character_tags_universe_user_idx;
CREATE INDEX IF NOT EXISTS character_tags_universe_user_idx ON public.character_tags(universe_id, user_id);
CREATE INDEX IF NOT EXISTS character_tags_character_idx     ON public.character_tags(character_id);

ALTER TABLE public.character_tags ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "character_tags_select" ON public.character_tags;
DROP POLICY IF EXISTS "character_tags_insert" ON public.character_tags;
DROP POLICY IF EXISTS "character_tags_delete" ON public.character_tags;
DROP POLICY IF EXISTS "Users manage their own followed tags" ON public.character_tags;
CREATE POLICY "character_tags_manage_own" ON public.character_tags
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- ── 2. Documents : document_tags + followed_document_tags → document_tags ──

DROP TABLE IF EXISTS public.document_tags CASCADE;
ALTER TABLE public.followed_document_tags RENAME TO document_tags;

ALTER TABLE public.document_tags DROP CONSTRAINT IF EXISTS followed_document_tags_pkey;
ALTER TABLE public.document_tags
  ADD CONSTRAINT document_tags_pkey PRIMARY KEY (universe_id, user_id, document_id, tag_id);

DROP INDEX IF EXISTS public.followed_document_tags_universe_user_idx;
CREATE INDEX IF NOT EXISTS document_tags_universe_user_idx ON public.document_tags(universe_id, user_id);
CREATE INDEX IF NOT EXISTS document_tags_document_idx      ON public.document_tags(document_id);

ALTER TABLE public.document_tags ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Users manage own document tags" ON public.document_tags;
DROP POLICY IF EXISTS "Users manage own followed doc tags" ON public.document_tags;
CREATE POLICY "document_tags_manage_own" ON public.document_tags
  FOR ALL USING (auth.uid() = user_id) WITH CHECK (auth.uid() = user_id);

-- ── 3. Fonctions obsolètes de partage/sync ────────────────────

DROP FUNCTION IF EXISTS public._cleanup_char_tags_on_transfer(UUID, UUID);
DROP FUNCTION IF EXISTS public._cleanup_doc_tags_on_transfer(UUID, UUID);
DROP FUNCTION IF EXISTS public.sync_owner_tags(TEXT, TEXT);
DROP FUNCTION IF EXISTS public.sync_char_tags_to_follower(UUID, UUID);
DROP FUNCTION IF EXISTS public.sync_doc_tags_to_follower(UUID, UUID);

-- ── 4. cleanup_orphan_char_tags / cleanup_orphan_doc_tags — adaptées ──

CREATE OR REPLACE FUNCTION public.cleanup_orphan_char_tags(
  p_user_id UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tag_id UUID;
BEGIN
  FOR v_tag_id IN
    SELECT t.id
    FROM   public.tags t
    WHERE  t.user_id = p_user_id
      AND  NOT EXISTS (
             SELECT 1 FROM public.character_tags ct
             WHERE ct.tag_id = t.id AND ct.user_id = p_user_id
           )
  LOOP
    DELETE FROM public.tags WHERE id = v_tag_id AND user_id = p_user_id;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_orphan_char_tags(UUID) TO authenticated;

CREATE OR REPLACE FUNCTION public.cleanup_orphan_doc_tags(
  p_user_id UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_tag_id UUID;
BEGIN
  FOR v_tag_id IN
    SELECT t.id
    FROM   public.doc_tags t
    WHERE  t.user_id = p_user_id
      AND  NOT EXISTS (
             SELECT 1 FROM public.document_tags dt
             WHERE dt.tag_id = t.id AND dt.user_id = p_user_id
           )
  LOOP
    DELETE FROM public.doc_tags WHERE id = v_tag_id AND user_id = p_user_id;
  END LOOP;
END;
$$;

GRANT EXECUTE ON FUNCTION public.cleanup_orphan_doc_tags(UUID) TO authenticated;

-- ── 5. transfer_item — ne nettoie plus les tags (ils restent à qui les a posés) ──

CREATE OR REPLACE FUNCTION public.transfer_item(
  p_item_type   TEXT,
  p_item_id     UUID,
  p_to_username TEXT
)
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_caller_id    UUID := auth.uid();
  v_target_id    UUID;
  v_item_user_id UUID;
  v_map_key      TEXT;
BEGIN
  IF v_caller_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authenticated');
  END IF;

  SELECT id INTO v_target_id
  FROM public.profiles
  WHERE lower(username) = lower(trim(p_to_username))
  LIMIT 1;

  IF v_target_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'user_not_found');
  END IF;

  IF v_target_id = v_caller_id THEN
    RETURN jsonb_build_object('ok', false, 'error', 'same_user');
  END IF;

  IF p_item_type = 'char' THEN
    SELECT user_id INTO v_item_user_id FROM public.characters WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.characters SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'chr' THEN
    SELECT user_id INTO v_item_user_id FROM public.chronicles WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.chronicles SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'doc' THEN
    SELECT user_id INTO v_item_user_id FROM public.documents WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    UPDATE public.documents SET user_id = v_target_id, updated_at = NOW() WHERE id = p_item_id;

  ELSIF p_item_type = 'map' THEN
    SELECT user_id, map_key INTO v_item_user_id, v_map_key FROM public.map_layers WHERE id = p_item_id;
    IF v_item_user_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'item_not_found'); END IF;
    IF v_item_user_id <> v_caller_id THEN RETURN jsonb_build_object('ok', false, 'error', 'not_owner'); END IF;
    -- Transfère uniquement les marqueurs de la carte concernée (comme avant).
    UPDATE public.map_markers
      SET user_id = v_target_id, updated_at = NOW()
      WHERE user_id = v_caller_id AND map_key = v_map_key;
    UPDATE public.map_layers
      SET user_id = v_target_id, updated_at = NOW()
      WHERE id = p_item_id;

  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'invalid_type');
  END IF;

  RETURN jsonb_build_object('ok', true, 'item_id', p_item_id, 'to_user_id', v_target_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.transfer_item(TEXT, UUID, TEXT) TO authenticated;

-- ── 6. remove_universe_member — idem, plus nettoyage tags du partant ──

CREATE OR REPLACE FUNCTION public.remove_universe_member(
  p_universe_id UUID,
  p_user_id     UUID
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner_id        UUID;
  v_map_key         TEXT;
  v_owner_has_layer BOOLEAN;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner_id
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner_id IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF p_user_id = v_owner_id THEN
    RAISE EXCEPTION 'Le propriétaire ne peut pas quitter son propre univers';
  END IF;

  IF auth.uid() <> p_user_id AND NOT public.has_universe_role(p_universe_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'Non autorisé';
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.universe_members
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  ) THEN
    RAISE EXCEPTION 'Cet utilisateur n''est pas membre de cet univers';
  END IF;

  -- ── Personnages / chroniques / documents : transfert direct au owner ──
  UPDATE public.characters SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id;
  UPDATE public.chronicles SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id;
  UPDATE public.documents SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id;

  -- ── Couches de carte + marqueurs ──────────────────────────
  -- map_layers a une contrainte UNIQUE(universe_id, user_id, map_key) : si le
  -- propriétaire possède déjà une couche pour cette carte, on fusionne
  -- les marqueurs dans la sienne et on supprime la couche devenue vide
  -- plutôt que de réassigner (ce qui violerait la contrainte).
  FOR v_map_key IN
    SELECT DISTINCT map_key FROM public.map_layers
    WHERE universe_id = p_universe_id AND user_id = p_user_id
  LOOP
    UPDATE public.map_markers
    SET user_id = v_owner_id, updated_at = NOW()
    WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;

    SELECT EXISTS (
      SELECT 1 FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = v_owner_id AND map_key = v_map_key
    ) INTO v_owner_has_layer;

    IF v_owner_has_layer THEN
      DELETE FROM public.map_layers
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    ELSE
      UPDATE public.map_layers
      SET user_id = v_owner_id, updated_at = NOW()
      WHERE universe_id = p_universe_id AND user_id = p_user_id AND map_key = v_map_key;
    END IF;
  END LOOP;

  -- ── Tags personnels du partant, pour cet univers ──────────────
  -- Ce sont ses tags à lui (indépendants des objets qu'il possédait) :
  -- ils n'ont plus de raison d'exister une fois qu'il a quitté l'univers.
  -- Cascade automatiquement sur character_tags / document_tags.
  DELETE FROM public.tags     WHERE universe_id = p_universe_id AND user_id = p_user_id;
  DELETE FROM public.doc_tags WHERE universe_id = p_universe_id AND user_id = p_user_id;

  -- ── Retrait de l'univers ───────────────────────────────────
  DELETE FROM public.universe_members
  WHERE universe_id = p_universe_id AND user_id = p_user_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.remove_universe_member(UUID, UUID) TO authenticated;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • character_tags(user_id, character_id, tag_id, universe_id) et
--    document_tags(user_id, document_id, tag_id, universe_id) sont
--    désormais les seules tables de liaison, quel que soit le
--    propriétaire de l'objet tagué.
--  • Le frontend doit appeler ces deux tables directement (avec
--    eq('user_id', currentUser.id)) au lieu de distinguer
--    character_tags / followed_character_tags.
--  • sync_owner_tags, sync_char_tags_to_follower, sync_doc_tags_to_follower,
--    _cleanup_char_tags_on_transfer, _cleanup_doc_tags_on_transfer
--    n'existent plus.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/25_unify_tags.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/26_map_layer_remove_title_description.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Suppression du titre et de la description des couches
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- (jusqu'à sql/25_unify_tags.sql inclus).
--
-- Une couche de carte (map_layers) n'a pas besoin de nom ni de
-- description : elle est entièrement définie par la carte à laquelle
-- elle est liée (map_key) et son propriétaire (user_id). Le frontend
-- identifie désormais une couche par le nom de la carte associée et
-- le nom d'utilisateur du propriétaire, jamais par un champ libre.
--
-- Migration destructive : les titres/descriptions existants sont perdus.
-- ══════════════════════════════════════════════════════════════

BEGIN;

ALTER TABLE public.map_layers DROP COLUMN IF EXISTS title;
ALTER TABLE public.map_layers DROP COLUMN IF EXISTS description;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • map_layers n'a plus de colonnes title/description.
--  • Toute requête sb.from('map_layers').select(...) doit être mise à
--    jour pour retirer ces champs (cf. map.js, campaigns.js, export.js).
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/26_map_layer_remove_title_description.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/28_storage_illustrations_fixes.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Corrections stockage des illustrations (orphelins)
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- (jusqu'à sql/27_map_markers_linked_object.sql inclus).
--
-- Ce script corrige trois problèmes découverts lors de l'audit
-- pré-stable :
--
-- 1. delete_universe() référence public.characters.illustration_url,
--    qui n'existe pas (l'URL est dans la colonne jsonb `data`). La
--    fonction levait systématiquement une erreur 42703 : la
--    suppression d'un univers échouait à 100 %.
--
-- 2. Les policies RLS de update/delete sur le bucket
--    character-illustrations exigeaient que le 1er segment du
--    chemin (le dossier) soit égal à auth.uid(). Or transfer_item()
--    et remove_universe_member() changent le propriétaire (user_id)
--    d'un personnage/document/chronique en base SANS déplacer le
--    fichier associé. Le nouvel propriétaire ne pouvait donc plus
--    jamais remplacer ni supprimer l'image existante (RLS refusée,
--    échec silencieux côté client car deleteStorageFile() n'inspecte
--    pas l'erreur retournée) → fuite garantie à chaque transfert.
--
-- 3. is_orphan_illustration() et list_orphan_illustrations()
--    existaient déjà en base de production mais dans aucun fichier
--    de migration versionné : elles auraient disparu à la moindre
--    reconstruction depuis sql/00_fresh_install.sql. Elles sont
--    reprises ici à l'identique (aucun changement de comportement),
--    et servent désormais aussi de garde-fou serveur pour le nettoyage
--    manuel des orphelins (cf. point 2 ci-dessous).
--
-- Rappel important : la suppression réelle d'un objet de Storage doit
-- TOUJOURS passer par l'API Storage (sb.storage.from(bucket).remove(...)
-- côté client). Un DELETE SQL direct sur storage.objects est bloqué par
-- Supabase (trigger storage.protect_delete) précisément pour éviter de
-- laisser les fichiers binaires orphelins côté S3 même si la ligne de
-- métadonnées disparaît. Ce script ne fait donc que corriger qui a le
-- droit d'appeler l'API Storage, jamais des DELETE directs.
-- ══════════════════════════════════════════════════════════════

-- ── 1. Fix delete_universe() ────────────────────────────────────
-- Les personnages stockent leur illustration dans data->>'illustration_url',
-- pas dans une colonne dédiée.
CREATE OR REPLACE FUNCTION public.delete_universe(p_universe_id UUID)
RETURNS TEXT[]
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner UUID;
  v_urls  TEXT[];
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF v_owner != auth.uid() THEN
    RAISE EXCEPTION 'Seul le propriétaire peut supprimer cet univers';
  END IF;

  -- Collecte les URLs d'illustration de tout l'univers (y compris les
  -- éléments privés créés par d'autres membres, invisibles via les
  -- policies RLS SELECT habituelles) pour nettoyage du storage côté client.
  SELECT COALESCE(array_agg(url), ARRAY[]::TEXT[]) INTO v_urls
  FROM (
    SELECT illustration_url AS url FROM public.universes  WHERE id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT (data->>'illustration_url') FROM public.characters WHERE universe_id = p_universe_id AND (data->>'illustration_url') IS NOT NULL AND (data->>'illustration_url') <> ''
    UNION ALL
    SELECT illustration_url FROM public.chronicles WHERE universe_id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT illustration_url FROM public.documents  WHERE universe_id = p_universe_id AND illustration_url <> ''
  ) t;

  -- SECURITY DEFINER : le cascade delete ci-dessous doit purger toutes les
  -- données de l'univers (personnages, chroniques, documents, campagnes,
  -- cartes...) même celles créées par d'autres membres, dont les policies
  -- RLS individuelles (auth.uid() = user_id) ne laisseraient pas le
  -- propriétaire de l'univers les supprimer directement.
  DELETE FROM public.universes WHERE id = p_universe_id;

  RETURN v_urls;
END;
$$;

GRANT EXECUTE ON FUNCTION public.delete_universe(UUID) TO authenticated;


-- ── 2. Détection des illustrations orphelines ───────────────────
-- Reprise à l'identique des fonctions déjà présentes en production
-- (non versionnées jusqu'ici) : un fichier est orphelin si aucune
-- ligne de universes/characters/chronicles/documents/maps ne pointe
-- vers lui.
CREATE OR REPLACE FUNCTION public.is_orphan_illustration(p_bucket_id TEXT, p_name TEXT)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT CASE p_bucket_id
    WHEN 'character-illustrations' THEN
      NOT EXISTS (SELECT 1 FROM public.characters  c WHERE (c.data->>'illustration_url') LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.chronicles c WHERE c.illustration_url LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.documents  d WHERE d.illustration_url LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.universes  u WHERE u.illustration_url LIKE '%' || p_name || '%')
    WHEN 'map-images' THEN
      NOT EXISTS (SELECT 1 FROM public.maps m WHERE m.image_url LIKE '%' || p_name || '%')
    ELSE FALSE
  END;
$$;

GRANT EXECUTE ON FUNCTION public.is_orphan_illustration(TEXT, TEXT) TO authenticated;

-- Liste les fichiers orphelins des deux buckets d'illustrations.
-- Réservé aux personnes possédant au moins un univers (évite qu'un
-- compte fraîchement créé puisse lister les noms de fichiers de
-- tout le monde).
CREATE OR REPLACE FUNCTION public.list_orphan_illustrations()
RETURNS TABLE(bucket_id TEXT, path TEXT, size_bytes BIGINT)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.universes u WHERE u.owner_id = auth.uid()) THEN
    RAISE EXCEPTION 'Seuls les propriétaires d''univers peuvent lister les fichiers orphelins.';
  END IF;

  RETURN QUERY
  SELECT o.bucket_id, o.name, (o.metadata->>'size')::bigint
  FROM storage.objects o
  WHERE o.bucket_id IN ('character-illustrations', 'map-images')
    AND public.is_orphan_illustration(o.bucket_id, o.name);
END;
$$;

GRANT EXECUTE ON FUNCTION public.list_orphan_illustrations() TO authenticated;


-- ── 3. RLS update/delete dynamique sur character-illustrations ──
-- Remplace la vérification statique "dossier == auth.uid()" par une
-- vérification à 3 niveaux :
--   a) dossier == auth.uid()            → comportement historique,
--      cas normal (pas de transfert).
--   b) propriété actuelle en base       → couvre le cas d'un
--      personnage/document/chronique/univers transféré à un autre
--      utilisateur (transfer_item / remove_universe_member) : le
--      nouveau propriétaire peut désormais remplacer ou supprimer
--      l'image même si elle est restée dans le dossier de l'ancien
--      propriétaire.
--   c) fichier confirmé orphelin        → n'importe quel utilisateur
--      connecté peut nettoyer un fichier dont is_orphan_illustration()
--      prouve côté serveur qu'il n'est référencé par rien. Un fichier
--      réellement utilisé ne peut jamais matcher cette clause.
CREATE OR REPLACE FUNCTION public.storage_can_manage_illustration(p_bucket_id TEXT, p_name TEXT)
RETURNS BOOLEAN
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_folder TEXT := (storage.foldername(p_name))[1];
  v_file   TEXT := split_part(p_name, '/', 2);
  v_id     UUID;
BEGIN
  IF v_folder = auth.uid()::text THEN
    RETURN TRUE;
  END IF;

  IF p_bucket_id = 'character-illustrations' THEN
    BEGIN
      v_id := (regexp_match(v_file, '^(?:doc_|chr_|universe_)?([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})'))[1]::uuid;
    EXCEPTION WHEN OTHERS THEN
      v_id := NULL;
    END;

    IF v_id IS NOT NULL AND (
      EXISTS (SELECT 1 FROM public.characters WHERE id = v_id AND user_id = auth.uid())
      OR EXISTS (SELECT 1 FROM public.documents  WHERE id = v_id AND user_id = auth.uid())
      OR EXISTS (SELECT 1 FROM public.chronicles WHERE id = v_id AND user_id = auth.uid())
      OR EXISTS (SELECT 1 FROM public.universes  WHERE id = v_id AND owner_id = auth.uid())
    ) THEN
      RETURN TRUE;
    END IF;
  END IF;

  RETURN public.is_orphan_illustration(p_bucket_id, p_name);
END;
$$;

GRANT EXECUTE ON FUNCTION public.storage_can_manage_illustration(TEXT, TEXT) TO authenticated;

DROP POLICY IF EXISTS "illustrations_update_own" ON storage.objects;
CREATE POLICY "illustrations_update_own"
  ON storage.objects FOR UPDATE
  TO authenticated
  USING (
    bucket_id = 'character-illustrations'
    AND public.storage_can_manage_illustration(bucket_id, name)
  );

DROP POLICY IF EXISTS "illustrations_delete_own" ON storage.objects;
CREATE POLICY "illustrations_delete_own"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'character-illustrations'
    AND public.storage_can_manage_illustration(bucket_id, name)
  );

-- Une policy "illustrations_delete_orphan_by_any_owner" existait déjà
-- (créée hors migration, cf. point 3 de l'en-tête) et n'autorisait le
-- nettoyage d'orphelins qu'aux propriétaires d'univers. Elle est
-- strictement subsumée par illustrations_delete_own ci-dessus (qui
-- couvre aussi le cas "orphelin" sans cette restriction) : on la
-- retire pour ne garder qu'une seule policy DELETE à lire.
DROP POLICY IF EXISTS "illustrations_delete_orphan_by_any_owner" ON storage.objects;

-- Idem côté map-images : la policy existait déjà hors migration. Elle
-- reste utile ici car storage_path_universe_role() exige d'être owner
-- DE CET UNIVERS précis, alors que celle-ci permet à N'IMPORTE QUEL
-- owner d'univers de nettoyer un fichier confirmé orphelin même dans
-- le dossier d'un autre univers (utile si un univers a été supprimé
-- par un autre biais que delete_universe()). On la reprend telle
-- quelle pour la verser en migration.
DROP POLICY IF EXISTS "map_images_delete_orphan_by_any_owner" ON storage.objects;
CREATE POLICY "map_images_delete_orphan_by_any_owner"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'map-images'
    AND EXISTS (SELECT 1 FROM public.universes u WHERE u.owner_id = auth.uid())
    AND public.is_orphan_illustration(bucket_id, name)
  );

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • delete_universe() ne référence plus une colonne inexistante :
--    la suppression d'univers fonctionne à nouveau.
--  • is_orphan_illustration() / list_orphan_illustrations() sont
--    désormais versionnées (elles existaient déjà en prod, ajoutées
--    hors migration).
--  • storage_can_manage_illustration() : après un transfert de
--    personnage/document/chronique/univers, le nouveau propriétaire
--    peut gérer l'illustration existante. N'importe quel utilisateur
--    connecté peut supprimer un fichier confirmé orphelin (vérifié
--    côté serveur, jamais sur la seule confiance du client).
--  • Aucun changement fonctionnel côté map-images : sa policy de
--    remplacement/suppression normale vérifie déjà le rôle courant
--    sur l'univers (storage_path_universe_role), pas un propriétaire
--    figé au moment de l'upload — elle ne souffre pas de ce bug.
--    Sa policy de nettoyage d'orphelins (map_images_delete_orphan_by_any_owner)
--    est simplement reprise à l'identique pour être versionnée.
--  • illustrations_delete_orphan_by_any_owner (character-illustrations)
--    est supprimée : redondante avec illustrations_delete_own qui
--    couvre déjà, plus largement, le nettoyage des orphelins.
--  • Rappel : le nettoyage réel des fichiers doit se faire via
--    sb.storage.from(bucket).remove([...]) côté client (ou tout appel
--    à l'API Storage), jamais via un DELETE SQL direct (bloqué par
--    Supabase de toute façon).
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/28_storage_illustrations_fixes.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/27_map_markers_linked_object.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Lien d'un marqueur de carte vers un objet de l'univers
-- À exécuter sur une base ayant déjà reçu sql/00_fresh_install.sql
-- (jusqu'à sql/26_map_layer_remove_title_description.sql inclus).
--
-- Un marqueur de carte peut désormais pointer vers un personnage ou
-- un document de l'univers. La popup d'information du marqueur
-- affiche alors un lien cliquable vers la fiche de cet objet.
-- ══════════════════════════════════════════════════════════════

BEGIN;

ALTER TABLE public.map_markers
  ADD COLUMN IF NOT EXISTS linked_type TEXT CHECK (linked_type IN ('char', 'doc')),
  ADD COLUMN IF NOT EXISTS linked_id UUID;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • map_markers gagne linked_type ('char'|'doc'|NULL) et linked_id
--    (uuid du personnage ou document lié, NULL si aucun lien).
--  • Toute requête sb.from('map_markers').select(...) doit inclure
--    ces deux colonnes (cf. map.js).
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/27_map_markers_linked_object.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/29_universe_pause.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Mise en pause des univers inactifs
-- À coller dans : Supabase Dashboard > SQL Editor > New query
--
-- Un univers que personne n'a visité depuis 2 mois est mis en
-- pause : toutes ses données (personnages, chroniques, documents,
-- campagnes, cartes...) sont sérialisées dans un unique blob JSONB
-- de public.universe_archives — compressé automatiquement par
-- Postgres via le mécanisme TOAST — puis supprimées des tables
-- vives. Seules la ligne universes (nom, illustration, badge
-- "en pause") et les lignes universe_members (accès, rôles)
-- restent en place.
--
-- La réactivation (resume_universe) réinsère toutes les lignes
-- archivées puis supprime l'archive. Tout est transactionnel :
-- en cas d'erreur, rien n'est perdu.
--
-- Les fonctions d'archivage sont génériques : elles découvrent via
-- le catalogue toute table portant une colonne universe_id (niveau 1)
-- ainsi que leurs tables filles sans universe_id (niveau 2, ex :
-- chronicle_entries, character_tags, campaign_members...). Une table
-- ajoutée par une future migration sera donc archivée automatiquement.
--
-- ⚠ Limite connue : si une future migration ajoute une colonne
-- NOT NULL sans DEFAULT-compatible à une table archivée, les archives
-- créées avant cette migration devront être backfillées avant
-- réactivation (jsonb_populate_recordset remplit les colonnes
-- manquantes avec NULL).
--
-- Déclenchement : pause_stale_universes() est appelée par le client
-- au chargement de la liste des univers et ne met en pause que les
-- univers POSSÉDÉS par l'appelant. touch_universe_visit() est appelée
-- à chaque entrée dans un univers (par n'importe quel membre).
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Colonnes de suivi sur universes ──────────────────────────
-- DEFAULT NOW() : les univers existants partent avec une visite
-- "aujourd'hui" pour ne pas être mis en pause dès la migration.

ALTER TABLE public.universes
  ADD COLUMN IF NOT EXISTS last_visited_at TIMESTAMPTZ NOT NULL DEFAULT NOW();

ALTER TABLE public.universes
  ADD COLUMN IF NOT EXISTS paused_at TIMESTAMPTZ;


-- ── 2. Le trigger updated_at ignore les champs de suivi ─────────
-- Sans cela, chaque visite (last_visited_at) fausserait la date
-- "Modifié" affichée sur les cards et l'ordre de tri des univers.

CREATE OR REPLACE FUNCTION public.handle_universe_updated_at()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF (to_jsonb(NEW) - 'updated_at' - 'last_visited_at' - 'paused_at')
     IS DISTINCT FROM
     (to_jsonb(OLD) - 'updated_at' - 'last_visited_at' - 'paused_at') THEN
    NEW.updated_at = NOW();
  END IF;
  RETURN NEW;
END;
$$;

DROP TRIGGER IF EXISTS on_universes_updated ON public.universes;
CREATE TRIGGER on_universes_updated
  BEFORE UPDATE ON public.universes
  FOR EACH ROW EXECUTE FUNCTION public.handle_universe_updated_at();


-- ── 3. Table d'archives (stockage à froid) ──────────────────────
-- payload : { "nom_de_table": [ligne, ligne, ...], ... }
-- Les valeurs JSONB volumineuses sont compressées par TOAST.

CREATE TABLE IF NOT EXISTS public.universe_archives (
  universe_id UUID PRIMARY KEY REFERENCES public.universes(id) ON DELETE CASCADE,
  payload     JSONB NOT NULL,
  archived_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- RLS sans policy : la table n'est accessible que via les fonctions
-- SECURITY DEFINER ci-dessous, jamais directement par les clients.
ALTER TABLE public.universe_archives ENABLE ROW LEVEL SECURITY;


-- ── 4. Suivi des visites ────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.touch_universe_visit(p_universe_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.is_universe_member(p_universe_id, auth.uid()) THEN
    RAISE EXCEPTION 'Seuls les membres de l''univers peuvent enregistrer une visite';
  END IF;

  UPDATE public.universes
  SET last_visited_at = NOW()
  WHERE id = p_universe_id;
END;
$$;


-- ── 5. Archivage (interne) ──────────────────────────────────────

CREATE OR REPLACE FUNCTION public._pause_universe_internal(p_universe_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_paused   TIMESTAMPTZ;
  v_payload  JSONB := '{}'::jsonb;
  v_tables   TEXT[];
  v_tbl      TEXT;
  v_rows     JSONB;
  v_child    RECORD;
BEGIN
  SELECT paused_at INTO v_paused
  FROM public.universes
  WHERE id = p_universe_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  -- Déjà en pause : ne surtout pas écraser l'archive existante
  -- avec le contenu (vide) des tables vives.
  IF v_paused IS NOT NULL THEN
    RETURN;
  END IF;

  -- Niveau 1 : toute table de public portant une colonne universe_id.
  -- universes et universe_members restent en place (affichage de la
  -- card et droits d'accès), universe_archives est le conteneur.
  SELECT COALESCE(array_agg(c.table_name::text), '{}') INTO v_tables
  FROM information_schema.columns c
  JOIN information_schema.tables t
    ON t.table_schema = c.table_schema
   AND t.table_name   = c.table_name
   AND t.table_type   = 'BASE TABLE'
  WHERE c.table_schema = 'public'
    AND c.column_name  = 'universe_id'
    AND c.table_name NOT IN ('universes', 'universe_members', 'universe_archives');

  FOREACH v_tbl IN ARRAY v_tables LOOP
    EXECUTE format(
      'SELECT COALESCE(jsonb_agg(to_jsonb(t)), ''[]''::jsonb) FROM public.%I t WHERE t.universe_id = $1',
      v_tbl
    ) INTO v_rows USING p_universe_id;
    v_payload := v_payload || jsonb_build_object(v_tbl, v_rows);
  END LOOP;

  -- Niveau 2 : tables sans universe_id référençant une table de
  -- niveau 1 (ex : chronicle_entries → chronicles). Une seule FK
  -- suffit pour sélectionner les lignes de l'univers.
  FOR v_child IN
    SELECT DISTINCT ON (con.conrelid)
           con.conrelid::regclass::text  AS child_table,
           a.attname::text               AS fk_col,
           con.confrelid::regclass::text AS parent_table,
           pa.attname::text              AS parent_col
    FROM pg_constraint con
    JOIN pg_attribute a  ON a.attrelid  = con.conrelid  AND a.attnum  = con.conkey[1]
    JOIN pg_attribute pa ON pa.attrelid = con.confrelid AND pa.attnum = con.confkey[1]
    WHERE con.contype = 'f'
      AND array_length(con.conkey, 1) = 1
      AND con.conrelid::regclass::text  <> ALL (ARRAY['universes', 'universe_members', 'universe_archives'])
      AND con.confrelid::regclass::text =  ANY (v_tables)
      AND NOT (con.conrelid::regclass::text = ANY (v_tables))
    ORDER BY con.conrelid, con.confrelid
  LOOP
    EXECUTE format(
      'SELECT COALESCE(jsonb_agg(to_jsonb(c)), ''[]''::jsonb)
         FROM public.%I c
        WHERE c.%I IN (SELECT p.%I FROM public.%I p WHERE p.universe_id = $1)',
      v_child.child_table, v_child.fk_col, v_child.parent_col, v_child.parent_table
    ) INTO v_rows USING p_universe_id;
    v_payload := v_payload || jsonb_build_object(v_child.child_table, v_rows);
  END LOOP;

  -- INSERT strict (pas de ON CONFLICT) : si une archive orpheline
  -- existait, on préfère échouer et tout annuler plutôt que l'écraser.
  INSERT INTO public.universe_archives (universe_id, payload)
  VALUES (p_universe_id, v_payload);

  -- Purge des tables vives ; les cascades FK vident le niveau 2.
  FOREACH v_tbl IN ARRAY v_tables LOOP
    EXECUTE format('DELETE FROM public.%I WHERE universe_id = $1', v_tbl)
    USING p_universe_id;
  END LOOP;

  UPDATE public.universes
  SET paused_at = NOW()
  WHERE id = p_universe_id;
END;
$$;


-- ── 6. Restauration (interne) ───────────────────────────────────

CREATE OR REPLACE FUNCTION public._resume_universe_internal(p_universe_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_payload   JSONB;
  v_remaining TEXT[];
  v_tbl       TEXT;
  v_progress  BOOLEAN;
  v_has_dep   BOOLEAN;
BEGIN
  SELECT payload INTO v_payload
  FROM public.universe_archives
  WHERE universe_id = p_universe_id;

  IF v_payload IS NULL THEN
    -- Pas d'archive (ne devrait pas arriver) : simple réactivation.
    UPDATE public.universes
    SET paused_at = NULL, last_visited_at = NOW()
    WHERE id = p_universe_id;
    RETURN;
  END IF;

  -- Tables encore existantes parmi celles archivées.
  SELECT COALESCE(array_agg(k), '{}') INTO v_remaining
  FROM jsonb_object_keys(v_payload) k
  WHERE to_regclass(format('public.%I', k)) IS NOT NULL;

  -- Insertion en ordre topologique : une table n'est réinsérée que
  -- lorsque toutes celles qu'elle référence (parmi les restantes)
  -- l'ont déjà été (ex : chronicles avant chronicle_entries).
  WHILE array_length(v_remaining, 1) IS NOT NULL LOOP
    v_progress := FALSE;

    FOREACH v_tbl IN ARRAY v_remaining LOOP
      SELECT EXISTS (
        SELECT 1
        FROM pg_constraint con
        WHERE con.contype = 'f'
          AND con.conrelid = to_regclass(format('public.%I', v_tbl))
          AND con.confrelid <> con.conrelid
          AND con.confrelid::regclass::text = ANY (v_remaining)
      ) INTO v_has_dep;

      IF NOT v_has_dep THEN
        EXECUTE format(
          'INSERT INTO public.%I SELECT * FROM jsonb_populate_recordset(NULL::public.%I, $1)',
          v_tbl, v_tbl
        ) USING v_payload -> v_tbl;
        v_remaining := array_remove(v_remaining, v_tbl);
        v_progress  := TRUE;
      END IF;
    END LOOP;

    IF NOT v_progress THEN
      RAISE EXCEPTION 'Dépendances circulaires entre tables lors de la restauration de l''univers %', p_universe_id;
    END IF;
  END LOOP;

  DELETE FROM public.universe_archives WHERE universe_id = p_universe_id;

  UPDATE public.universes
  SET paused_at = NULL, last_visited_at = NOW()
  WHERE id = p_universe_id;
END;
$$;


-- ── 7. Fonctions exposées aux clients ───────────────────────────

-- Mise en pause manuelle (propriétaire uniquement). Sert aussi à
-- tester le flux sans attendre 2 mois d'inactivité.
CREATE OR REPLACE FUNCTION public.pause_universe(p_universe_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF v_owner != auth.uid() THEN
    RAISE EXCEPTION 'Seul le propriétaire peut mettre cet univers en pause';
  END IF;

  PERFORM public._pause_universe_internal(p_universe_id);
END;
$$;

-- Mise en pause automatique : appelée au chargement de la liste des
-- univers, elle archive les univers possédés par l'appelant que
-- personne (propriétaire ou membre) n'a visités depuis 2 mois.
-- Renvoie les ids mis en pause à l'instant.
CREATE OR REPLACE FUNCTION public.pause_stale_universes()
RETURNS SETOF UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id UUID;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  FOR v_id IN
    SELECT id
    FROM public.universes
    WHERE owner_id = auth.uid()
      AND paused_at IS NULL
      AND last_visited_at < NOW() - INTERVAL '2 months'
  LOOP
    PERFORM public._pause_universe_internal(v_id);
    RETURN NEXT v_id;
  END LOOP;
END;
$$;

-- Réactivation : ouverte à tout membre de l'univers, pour qu'un
-- joueur ne soit pas bloqué si le propriétaire est absent.
CREATE OR REPLACE FUNCTION public.resume_universe(p_universe_id UUID)
RETURNS public.universes
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_universe public.universes;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.is_universe_member(p_universe_id, auth.uid()) THEN
    RAISE EXCEPTION 'Seuls les membres de l''univers peuvent le réactiver';
  END IF;

  SELECT * INTO v_universe
  FROM public.universes
  WHERE id = p_universe_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF v_universe.paused_at IS NOT NULL THEN
    PERFORM public._resume_universe_internal(p_universe_id);
    SELECT * INTO v_universe
    FROM public.universes
    WHERE id = p_universe_id;
  END IF;

  RETURN v_universe;
END;
$$;


-- ── 8. Droits ───────────────────────────────────────────────────

GRANT EXECUTE ON FUNCTION public.touch_universe_visit(UUID)   TO authenticated;
GRANT EXECUTE ON FUNCTION public.pause_universe(UUID)         TO authenticated;
GRANT EXECUTE ON FUNCTION public.pause_stale_universes()      TO authenticated;
GRANT EXECUTE ON FUNCTION public.resume_universe(UUID)        TO authenticated;

-- Les fonctions internes ne doivent jamais être appelées directement
-- (aucun contrôle d'autorisation à l'intérieur).
REVOKE ALL ON FUNCTION public._pause_universe_internal(UUID)  FROM PUBLIC, anon, authenticated;
REVOKE ALL ON FUNCTION public._resume_universe_internal(UUID) FROM PUBLIC, anon, authenticated;


-- ── 9. Les images des univers archivés ne sont pas orphelines ───
-- Le nettoyage manuel des fichiers orphelins (cf. 28) ne voit plus
-- les lignes archivées : sans ce garde-fou, il proposerait de
-- supprimer les illustrations des univers en pause.

CREATE OR REPLACE FUNCTION public.is_orphan_illustration(p_bucket_id TEXT, p_name TEXT)
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT CASE p_bucket_id
    WHEN 'character-illustrations' THEN
      NOT EXISTS (SELECT 1 FROM public.characters  c WHERE (c.data->>'illustration_url') LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.chronicles c WHERE c.illustration_url LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.documents  d WHERE d.illustration_url LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.universes  u WHERE u.illustration_url LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.universe_archives a WHERE a.payload::text LIKE '%' || p_name || '%')
    WHEN 'map-images' THEN
      NOT EXISTS (SELECT 1 FROM public.maps m WHERE m.image_url LIKE '%' || p_name || '%')
      AND NOT EXISTS (SELECT 1 FROM public.universe_archives a WHERE a.payload::text LIKE '%' || p_name || '%')
    ELSE FALSE
  END;
$$;

GRANT EXECUTE ON FUNCTION public.is_orphan_illustration(TEXT, TEXT) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/29_universe_pause.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/30_admin_panel.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Panneau d'administration
-- À coller dans : Supabase Dashboard > SQL Editor > New query
--
-- Ajoute une table admin_users listant les comptes autorisés à
-- accéder au panneau d'administration (statistiques + purge des
-- fichiers orphelins), et les fonctions RPC nécessaires :
--
--   - is_admin()                        : le compte courant est-il admin ?
--   - admin_get_stats()                 : statistiques globales (JSONB)
--   - admin_list_orphan_illustrations() : liste des fichiers orphelins,
--     réservée aux admins (contrairement à list_orphan_illustrations
--     qui exige de posséder un univers, cf. 28_storage_illustrations_fixes.sql)
--
-- admin_users n'a aucune policy RLS : elle n'est lisible que via les
-- fonctions SECURITY DEFINER ci-dessous, jamais directement par les
-- clients (même pattern que universe_archives, cf. 29_universe_pause.sql).
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Table des comptes administrateurs ────────────────────────

CREATE TABLE IF NOT EXISTS public.admin_users (
  user_id    UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.admin_users ENABLE ROW LEVEL SECURITY;

-- Bootstrap : compte historique de l'éditeur du projet (onirim.bzh).
INSERT INTO public.admin_users (user_id)
VALUES ('63ec7d72-765d-428d-8c5e-18955d2749d3')
ON CONFLICT DO NOTHING;


-- ── 2. is_admin() ────────────────────────────────────────────────
-- Sans argument : ne renseigne jamais que sur le compte courant, donc
-- sans risque à exposer à tout utilisateur connecté (sert aussi à
-- décider côté client si l'entrée de menu doit être affichée).

CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT EXISTS (SELECT 1 FROM public.admin_users WHERE user_id = auth.uid());
$$;

GRANT EXECUTE ON FUNCTION public.is_admin() TO authenticated;


-- ── 3. Statistiques globales ─────────────────────────────────────

CREATE OR REPLACE FUNCTION public.admin_get_stats()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_characters       BIGINT;
  v_chronicles       BIGINT;
  v_documents        BIGINT;
  v_campaigns        BIGINT;
  v_maps             BIGINT;
  v_universes_active BIGINT;
  v_universes_paused BIGINT;
  v_storage_bytes    BIGINT;
  v_db_bytes         BIGINT;
  v_orphan_count     BIGINT;
  v_orphan_bytes     BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  SELECT count(*) INTO v_characters FROM public.characters;
  SELECT count(*) INTO v_chronicles FROM public.chronicles;
  SELECT count(*) INTO v_documents  FROM public.documents;
  SELECT count(*) INTO v_campaigns  FROM public.campaigns;
  SELECT count(*) INTO v_maps       FROM public.maps;

  SELECT count(*) FILTER (WHERE paused_at IS NULL),
         count(*) FILTER (WHERE paused_at IS NOT NULL)
    INTO v_universes_active, v_universes_paused
    FROM public.universes;

  SELECT COALESCE(SUM((o.metadata->>'size')::bigint), 0) INTO v_storage_bytes
  FROM storage.objects o;

  SELECT pg_database_size(current_database()) INTO v_db_bytes;

  SELECT count(*), COALESCE(SUM((o.metadata->>'size')::bigint), 0)
    INTO v_orphan_count, v_orphan_bytes
    FROM storage.objects o
    WHERE o.bucket_id IN ('character-illustrations', 'map-images')
      AND public.is_orphan_illustration(o.bucket_id, o.name);

  RETURN jsonb_build_object(
    'objects', jsonb_build_object(
      'characters', v_characters,
      'chronicles', v_chronicles,
      'documents',  v_documents,
      'campaigns',  v_campaigns,
      'maps',       v_maps,
      'total',      v_characters + v_chronicles + v_documents + v_campaigns + v_maps
    ),
    'universes', jsonb_build_object(
      'active', v_universes_active,
      'paused', v_universes_paused,
      'total',  v_universes_active + v_universes_paused
    ),
    'orphans', jsonb_build_object(
      'count', v_orphan_count,
      'bytes', v_orphan_bytes
    ),
    'storage', jsonb_build_object(
      'bytes',       v_storage_bytes,
      'limit_bytes', 1073741824  -- 1 GB (plan gratuit Supabase)
    ),
    'database', jsonb_build_object(
      'bytes',       v_db_bytes,
      'limit_bytes', 524288000   -- 500 MB (plan gratuit Supabase)
    )
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_get_stats() TO authenticated;


-- ── 4. Liste des orphelins réservée aux admins ──────────────────
-- Identique à list_orphan_illustrations() mais sans l'exigence de
-- posséder un univers : un admin peut ne pas en posséder un.

CREATE OR REPLACE FUNCTION public.admin_list_orphan_illustrations()
RETURNS TABLE(bucket_id TEXT, path TEXT, size_bytes BIGINT)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  RETURN QUERY
  SELECT o.bucket_id, o.name, (o.metadata->>'size')::bigint
  FROM storage.objects o
  WHERE o.bucket_id IN ('character-illustrations', 'map-images')
    AND public.is_orphan_illustration(o.bucket_id, o.name);
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_list_orphan_illustrations() TO authenticated;

COMMIT;

-- ==================================================
-- END sql/30_admin_panel.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/31_admin_users_universes.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Panneau d'administration : gestion utilisateurs/univers
-- À coller dans : Supabase Dashboard > SQL Editor > New query
-- Nécessite sql/30_admin_panel.sql (is_admin(), is_orphan_illustration()).
--
-- Ajoute au panneau d'administration :
--   - admin_list_users()                 : liste des comptes avec leur
--     nombre d'univers possédés, d'objets créés, et leur limite
--     d'univers (profiles.max_universes, déjà utilisée par
--     create_universe/transfer_universe_ownership dans 00_fresh_install.sql).
--   - admin_set_user_max_universes(uuid, int) : modifie cette limite.
--   - admin_list_universes()             : liste des univers avec
--     propriétaire, nombre de membres et d'objets, statut pause.
--   - admin_pause_universe(uuid)         : met en pause n'importe quel
--     univers (réutilise _pause_universe_internal, sans exiger d'en
--     être propriétaire).
--   - admin_resume_universe(uuid)        : réactive n'importe quel
--     univers (réutilise _resume_universe_internal, sans exiger d'en
--     être membre).
--   - admin_delete_universe(uuid)        : supprime n'importe quel
--     univers (même logique que delete_universe, sans exigence de
--     propriété), renvoie les URLs d'illustration à nettoyer côté
--     storage côté client.
--
-- Toutes ces fonctions revérifient is_admin() indépendamment du menu
-- masqué côté client.
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Liste des utilisateurs ────────────────────────────────────
-- Remplacée plus bas par la version finale (sql/32 puis sql/33) :
-- colonnes qualifiées + cast email::text.

CREATE OR REPLACE FUNCTION public.admin_set_user_max_universes(p_user_id UUID, p_max_universes INT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  IF p_max_universes < 0 THEN
    RAISE EXCEPTION 'La limite doit être positive ou nulle';
  END IF;

  UPDATE public.profiles SET max_universes = p_max_universes WHERE id = p_user_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Utilisateur introuvable';
  END IF;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_set_user_max_universes(UUID, INT) TO authenticated;


-- ── 2. Pause / réactivation par un administrateur ────────────────
-- Contrairement à pause_universe()/resume_universe() (cf.
-- 29_universe_pause.sql), aucune exigence de propriété ou de
-- membership : un admin peut agir sur n'importe quel univers.

CREATE OR REPLACE FUNCTION public.admin_pause_universe(p_universe_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.universes WHERE id = p_universe_id) THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  PERFORM public._pause_universe_internal(p_universe_id);
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_pause_universe(UUID) TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_resume_universe(p_universe_id UUID)
RETURNS public.universes
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_universe public.universes;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  SELECT * INTO v_universe FROM public.universes WHERE id = p_universe_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF v_universe.paused_at IS NOT NULL THEN
    PERFORM public._resume_universe_internal(p_universe_id);
    SELECT * INTO v_universe FROM public.universes WHERE id = p_universe_id;
  END IF;

  RETURN v_universe;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_resume_universe(UUID) TO authenticated;


-- ── 3. Suppression par un administrateur ─────────────────────────
-- Même logique que delete_universe() (cf. 28_storage_illustrations_fixes.sql)
-- mais sans exiger d'en être propriétaire.
-- Note : si l'univers est en pause, ses personnages/chroniques/documents
-- sont déjà archivés dans universe_archives (colonnes vides dans les
-- tables vives) : leurs illustrations ne sont donc pas listées ici,
-- mais universe_archives est supprimée en cascade avec l'univers, ce
-- qui rend ces fichiers orphelins — ils seront nettoyés par la purge
-- des orphelins. C'est le même comportement que delete_universe().

CREATE OR REPLACE FUNCTION public.admin_delete_universe(p_universe_id UUID)
RETURNS TEXT[]
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_urls TEXT[];
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.universes WHERE id = p_universe_id) THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  SELECT COALESCE(array_agg(url), ARRAY[]::TEXT[]) INTO v_urls
  FROM (
    SELECT illustration_url AS url FROM public.universes  WHERE id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT (data->>'illustration_url') FROM public.characters WHERE universe_id = p_universe_id AND (data->>'illustration_url') IS NOT NULL AND (data->>'illustration_url') <> ''
    UNION ALL
    SELECT illustration_url FROM public.chronicles WHERE universe_id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT illustration_url FROM public.documents  WHERE universe_id = p_universe_id AND illustration_url <> ''
  ) t;

  DELETE FROM public.universes WHERE id = p_universe_id;

  RETURN v_urls;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_delete_universe(UUID) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/31_admin_users_universes.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/32_admin_list_ambiguous_fix.sql + sql/33_admin_list_users_email_cast.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — admin_list_users() / admin_list_universes() : version finale
-- Fusion des correctifs sql/32 (colonnes ambiguës) et sql/33 (cast email).
-- ══════════════════════════════════════════════════════════════

BEGIN;

CREATE OR REPLACE FUNCTION public.admin_list_users()
RETURNS TABLE(
  user_id         UUID,
  username        TEXT,
  email           TEXT,
  max_universes   INT,
  owned_universes BIGINT,
  objects_count   BIGINT,
  created_at      TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.username,
    au.email::text,
    p.max_universes,
    COALESCE(uc.owned_count, 0),
    COALESCE(oc.total, 0),
    au.created_at
  FROM public.profiles p
  JOIN auth.users au ON au.id = p.id
  LEFT JOIN (
    SELECT un.owner_id AS oid, count(*) AS owned_count
    FROM public.universes un
    GROUP BY un.owner_id
  ) uc ON uc.oid = p.id
  LEFT JOIN (
    SELECT t.uid, count(*) AS total FROM (
      SELECT c.user_id  AS uid FROM public.characters c
      UNION ALL SELECT ch.user_id AS uid FROM public.chronicles ch
      UNION ALL SELECT d.user_id  AS uid FROM public.documents d
      UNION ALL SELECT cp.user_id AS uid FROM public.campaigns cp
      UNION ALL SELECT m.created_by AS uid FROM public.maps m
    ) t
    GROUP BY t.uid
  ) oc ON oc.uid = p.id
  ORDER BY au.created_at;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_list_users() TO authenticated;


CREATE OR REPLACE FUNCTION public.admin_list_universes()
RETURNS TABLE(
  universe_id    UUID,
  name           TEXT,
  owner_id       UUID,
  owner_username TEXT,
  paused_at      TIMESTAMPTZ,
  created_at     TIMESTAMPTZ,
  member_count   BIGINT,
  objects_count  BIGINT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  RETURN QUERY
  SELECT
    un.id,
    un.name,
    un.owner_id,
    p.username,
    un.paused_at,
    un.created_at,
    COALESCE(mc.member_count, 0),
    COALESCE(oc.total, 0)
  FROM public.universes un
  LEFT JOIN public.profiles p ON p.id = un.owner_id
  LEFT JOIN (
    SELECT um.universe_id AS uwid, count(*) AS member_count
    FROM public.universe_members um
    GROUP BY um.universe_id
  ) mc ON mc.uwid = un.id
  LEFT JOIN (
    SELECT t.uwid, count(*) AS total FROM (
      SELECT c.universe_id  AS uwid FROM public.characters c
      UNION ALL SELECT ch.universe_id AS uwid FROM public.chronicles ch
      UNION ALL SELECT d.universe_id  AS uwid FROM public.documents d
      UNION ALL SELECT cp.universe_id AS uwid FROM public.campaigns cp
      UNION ALL SELECT ma.universe_id AS uwid FROM public.maps ma
    ) t
    GROUP BY t.uwid
  ) oc ON oc.uwid = un.id
  ORDER BY un.created_at DESC;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_list_universes() TO authenticated;

COMMIT;

-- ==================================================
-- END sql/32_admin_list_ambiguous_fix.sql + sql/33_admin_list_users_email_cast.sql
