-- ==================================================
-- BEGIN sql/36_admin_user_stats.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Panneau d'administration : statistiques utilisateurs
-- À coller dans : Supabase Dashboard > SQL Editor > New query
-- Nécessite sql/30_admin_panel.sql déjà appliqué.
--
-- Ajoute à admin_get_stats() un bloc "users" :
--   - total     : nombre total de comptes (auth.users)
--   - active_30d : comptes connectés au moins une fois dans les 30
--     derniers jours (auth.users.last_sign_in_at, renseigné par
--     Supabase Auth à chaque connexion — aucune table de suivi
--     supplémentaire nécessaire).
-- ══════════════════════════════════════════════════════════════

BEGIN;

CREATE OR REPLACE FUNCTION public.admin_get_stats()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_characters       BIGINT;
  v_chronicles       BIGINT;
  v_documents        BIGINT;
  v_campaigns        BIGINT;
  v_maps             BIGINT;
  v_universes_active BIGINT;
  v_universes_paused BIGINT;
  v_storage_bytes    BIGINT;
  v_db_bytes         BIGINT;
  v_orphan_count     BIGINT;
  v_orphan_bytes     BIGINT;
  v_users_total      BIGINT;
  v_users_active     BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  SELECT count(*) INTO v_characters FROM public.characters;
  SELECT count(*) INTO v_chronicles FROM public.chronicles;
  SELECT count(*) INTO v_documents  FROM public.documents;
  SELECT count(*) INTO v_campaigns  FROM public.campaigns;
  SELECT count(*) INTO v_maps       FROM public.maps;

  SELECT count(*) FILTER (WHERE paused_at IS NULL),
         count(*) FILTER (WHERE paused_at IS NOT NULL)
    INTO v_universes_active, v_universes_paused
    FROM public.universes;

  SELECT count(*),
         count(*) FILTER (WHERE last_sign_in_at >= now() - interval '30 days')
    INTO v_users_total, v_users_active
    FROM auth.users;

  SELECT COALESCE(SUM((o.metadata->>'size')::bigint), 0) INTO v_storage_bytes
  FROM storage.objects o;

  SELECT pg_database_size(current_database()) INTO v_db_bytes;

  SELECT count(*), COALESCE(SUM((o.metadata->>'size')::bigint), 0)
    INTO v_orphan_count, v_orphan_bytes
    FROM storage.objects o
    WHERE o.bucket_id IN ('character-illustrations', 'map-images')
      AND public.is_orphan_illustration(o.bucket_id, o.name);

  RETURN jsonb_build_object(
    'objects', jsonb_build_object(
      'characters', v_characters,
      'chronicles', v_chronicles,
      'documents',  v_documents,
      'campaigns',  v_campaigns,
      'maps',       v_maps,
      'total',      v_characters + v_chronicles + v_documents + v_campaigns + v_maps
    ),
    'universes', jsonb_build_object(
      'active', v_universes_active,
      'paused', v_universes_paused,
      'total',  v_universes_active + v_universes_paused
    ),
    'users', jsonb_build_object(
      'total',     v_users_total,
      'active_30d', v_users_active
    ),
    'orphans', jsonb_build_object(
      'count', v_orphan_count,
      'bytes', v_orphan_bytes
    ),
    'storage', jsonb_build_object(
      'bytes',       v_storage_bytes,
      'limit_bytes', 1073741824  -- 1 GB (plan gratuit Supabase)
    ),
    'database', jsonb_build_object(
      'bytes',       v_db_bytes,
      'limit_bytes', 524288000   -- 500 MB (plan gratuit Supabase)
    )
  );
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_get_stats() TO authenticated;

COMMIT;

-- ==================================================
-- END sql/36_admin_user_stats.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/37_gm_owner_curation_visibility_fix.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : verrou circulaire sur la curation
-- des objets publics par campagne (introduit par sql/35)
-- À exécuter sur une base ayant déjà reçu sql/35_campaign_gm_management.sql.
--
-- Constat : depuis sql/35, dès qu'au moins une campagne existe dans
-- un univers, un objet public (personnage, chronique, document,
-- carte) n'est visible aux autres membres que s'il a été coché dans
-- campaign_visible_* pour une campagne commune. Mais le sélecteur de
-- curation (campaigns.js: loadPublicObjectOptions) interroge les
-- tables characters/chronicles/documents/map_layers avec un simple
-- SELECT, soumis à la même policy RLS restrictive.
--
-- Résultat : un objet public créé par un simple joueur (ni owner ni
-- gm) après la création d'une première campagne dans l'univers
-- devient invisible pour tout le monde, y compris pour le MJ et le
-- propriétaire de l'univers — qui n'ont donc physiquement aucun
-- moyen de le voir pour le cocher dans campaign_visible_*. Verrou
-- circulaire : il faudrait qu'il soit déjà coché pour pouvoir le
-- voir et le cocher.
--
-- Correctif : le propriétaire et le MJ de l'univers doivent pouvoir
-- voir tout objet public de leur univers, indépendamment de la
-- curation par campagne — exactement comme campaigns_select leur
-- donne déjà une vue complète des campagnes via has_universe_role.
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- Personnages
DROP POLICY IF EXISTS "characters_select" ON public.characters;
CREATE POLICY "characters_select" ON public.characters FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND (
        public.has_universe_role(universe_id, ARRAY['owner', 'gm'])
        OR (
          public.shares_campaign_with(universe_id, user_id, auth.uid())
          AND (
            NOT public.campaign_content_restricted(universe_id)
            OR EXISTS (
              SELECT 1
              FROM public.campaign_members cm
              JOIN public.campaigns c ON c.id = cm.campaign_id
              JOIN public.campaign_visible_characters cvc ON cvc.campaign_id = c.id
              WHERE c.universe_id = characters.universe_id
                AND cm.user_id = auth.uid()
                AND cvc.character_id = characters.id
            )
          )
        )
      )
    )
  );

-- Chroniques
DROP POLICY IF EXISTS "chronicles_select" ON public.chronicles;
CREATE POLICY "chronicles_select" ON public.chronicles FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND (
        public.has_universe_role(universe_id, ARRAY['owner', 'gm'])
        OR (
          public.shares_campaign_with(universe_id, user_id, auth.uid())
          AND (
            NOT public.campaign_content_restricted(universe_id)
            OR EXISTS (
              SELECT 1
              FROM public.campaign_members cm
              JOIN public.campaigns c ON c.id = cm.campaign_id
              JOIN public.campaign_visible_chronicles cvc ON cvc.campaign_id = c.id
              WHERE c.universe_id = chronicles.universe_id
                AND cm.user_id = auth.uid()
                AND cvc.chronicle_id = chronicles.id
            )
          )
        )
      )
    )
  );

-- Documents
DROP POLICY IF EXISTS "documents_select" ON public.documents;
CREATE POLICY "documents_select" ON public.documents FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND (
        public.has_universe_role(universe_id, ARRAY['owner', 'gm'])
        OR (
          public.shares_campaign_with(universe_id, user_id, auth.uid())
          AND (
            NOT public.campaign_content_restricted(universe_id)
            OR EXISTS (
              SELECT 1
              FROM public.campaign_members cm
              JOIN public.campaigns c ON c.id = cm.campaign_id
              JOIN public.campaign_visible_documents cvd ON cvd.campaign_id = c.id
              WHERE c.universe_id = documents.universe_id
                AND cm.user_id = auth.uid()
                AND cvd.document_id = documents.id
            )
          )
        )
      )
    )
  );

-- Couches de carte
DROP POLICY IF EXISTS "map_layers_select" ON public.map_layers;
CREATE POLICY "map_layers_select" ON public.map_layers FOR SELECT
  USING (
    auth.uid() = user_id
    OR (
      is_public = TRUE
      AND (
        public.has_universe_role(universe_id, ARRAY['owner', 'gm'])
        OR (
          public.shares_campaign_with(universe_id, user_id, auth.uid())
          AND (
            NOT public.campaign_content_restricted(universe_id)
            OR EXISTS (
              SELECT 1
              FROM public.campaign_members cm
              JOIN public.campaigns c ON c.id = cm.campaign_id
              JOIN public.campaign_visible_maps cvm ON cvm.campaign_id = c.id
              WHERE c.universe_id = map_layers.universe_id
                AND cm.user_id = auth.uid()
                AND cvm.map_layer_id = map_layers.id
            )
          )
        )
      )
    )
  );

-- Marqueurs de carte
DROP POLICY IF EXISTS "map_markers_select_shared" ON public.map_markers;
CREATE POLICY "map_markers_select_shared" ON public.map_markers FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.map_layers ml
      WHERE ml.user_id  = map_markers.user_id
        AND ml.map_key  = map_markers.map_key
        AND ml.is_public = TRUE
        AND (
          public.has_universe_role(ml.universe_id, ARRAY['owner', 'gm'])
          OR (
            public.shares_campaign_with(ml.universe_id, ml.user_id, auth.uid())
            AND (
              NOT public.campaign_content_restricted(ml.universe_id)
              OR EXISTS (
                SELECT 1
                FROM public.campaign_members cm
                JOIN public.campaigns c ON c.id = cm.campaign_id
                JOIN public.campaign_visible_maps cvm ON cvm.campaign_id = c.id
                WHERE c.universe_id = ml.universe_id
                  AND cm.user_id = auth.uid()
                  AND cvm.map_layer_id = ml.id
              )
            )
          )
        )
    )
  );

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Fin — voir campaigns.js (loadPublicObjectOptions) pour la partie
-- frontend qui dépendait de ce correctif.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/37_gm_owner_curation_visibility_fix.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/38_entries_and_markers_gm_visibility_fix.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : propagation manquante du bypass
-- MJ/propriétaire (sql/37) sur les entrées de chronique et les
-- marqueurs de carte.
-- À exécuter sur une base ayant déjà reçu sql/37_gm_owner_curation_visibility_fix.sql.
--
-- Constat : sql/37 a ajouté un bypass permettant au MJ/propriétaire
-- de voir tout objet public de son univers, indépendamment de la
-- curation par campagne — mais seulement sur characters, chronicles,
-- documents et map_layers.
--
-- Deux policies dérivées n'ont pas reçu ce bypass, alors qu'elles
-- réimplémentent leur propre copie de la même logique de visibilité
-- au lieu de simplement suivre celle de leur table parente :
--   - chronicle_entries.entries_select (dérivée de chronicles)
--   - map_markers.map_markers_select_shared (dérivée de map_layers)
--
-- Résultat : une chronique redevenue visible pour le MJ/propriétaire
-- grâce à sql/37 pouvait rester vide côté entrées, tant qu'elle
-- n'était pas explicitement curée pour une campagne — même incohérence
-- pour les marqueurs d'une couche de carte publique.
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- Entrées de chronique
DROP POLICY IF EXISTS "entries_select" ON public.chronicle_entries;
CREATE POLICY "entries_select" ON public.chronicle_entries FOR SELECT
  USING (EXISTS (
    SELECT 1 FROM public.chronicles c
    WHERE c.id = chronicle_entries.chronicle_id
      AND (
        c.user_id = auth.uid()
        OR (
          c.is_public = TRUE
          AND (
            public.has_universe_role(c.universe_id, ARRAY['owner', 'gm'])
            OR (
              public.shares_campaign_with(c.universe_id, c.user_id, auth.uid())
              AND (
                NOT public.campaign_content_restricted(c.universe_id)
                OR EXISTS (
                  SELECT 1
                  FROM public.campaign_members cm
                  JOIN public.campaigns cc ON cc.id = cm.campaign_id
                  JOIN public.campaign_visible_chronicles cvc ON cvc.campaign_id = cc.id
                  WHERE cc.universe_id = c.universe_id
                    AND cm.user_id = auth.uid()
                    AND cvc.chronicle_id = c.id
                )
              )
            )
          )
        )
      )
  ));

-- Marqueurs de carte
DROP POLICY IF EXISTS "map_markers_select_shared" ON public.map_markers;
CREATE POLICY "map_markers_select_shared" ON public.map_markers FOR SELECT
  TO authenticated
  USING (
    EXISTS (
      SELECT 1 FROM public.map_layers ml
      WHERE ml.user_id  = map_markers.user_id
        AND ml.map_key  = map_markers.map_key
        AND ml.is_public = TRUE
        AND (
          public.has_universe_role(ml.universe_id, ARRAY['owner', 'gm'])
          OR (
            public.shares_campaign_with(ml.universe_id, ml.user_id, auth.uid())
            AND (
              NOT public.campaign_content_restricted(ml.universe_id)
              OR EXISTS (
                SELECT 1
                FROM public.campaign_members cm
                JOIN public.campaigns c ON c.id = cm.campaign_id
                JOIN public.campaign_visible_maps cvm ON cvm.campaign_id = c.id
                WHERE c.universe_id = ml.universe_id
                  AND cm.user_id = auth.uid()
                  AND cvm.map_layer_id = ml.id
              )
            )
          )
        )
    )
  );

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Fin.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/38_entries_and_markers_gm_visibility_fix.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/39_universe_invite_links.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Liens d'invitation d'univers
--
-- Remplace l'invitation par nom d'utilisateur par un lien à la
-- Discord : le propriétaire génère une URL, valable 7 jours, que
-- n'importe quel utilisateur du site peut ouvrir pour voir un
-- aperçu de l'univers (illustration, nom, description) et
-- confirmer son adhésion.
--
-- Un seul lien actif par univers : le régénérer invalide l'ancien.
-- ══════════════════════════════════════════════════════════════

BEGIN;

CREATE TABLE IF NOT EXISTS public.universe_invites (
  universe_id UUID PRIMARY KEY REFERENCES public.universes(id) ON DELETE CASCADE,
  token       TEXT NOT NULL UNIQUE,
  created_by  UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at  TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  expires_at  TIMESTAMPTZ NOT NULL
);

ALTER TABLE public.universe_invites ENABLE ROW LEVEL SECURITY;

-- Seuls le propriétaire/admin de l'univers peuvent voir le lien actif
-- (pour l'afficher dans l'écran de configuration). Le flux de
-- consultation/adhésion côté invité passe par les fonctions
-- SECURITY DEFINER ci-dessous, qui contournent la RLS.
DROP POLICY IF EXISTS "universe_invites_select_admin" ON public.universe_invites;
CREATE POLICY "universe_invites_select_admin"
  ON public.universe_invites FOR SELECT
  USING (public.has_universe_role(universe_id, ARRAY['owner','admin']));

-- ══════════════════════════════════════════════════════════════
-- Génération / régénération du lien (propriétaire ou admin)
-- ══════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.generate_universe_invite(p_universe_id UUID)
RETURNS TABLE(token TEXT, expires_at TIMESTAMPTZ)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_token   TEXT;
  v_expires TIMESTAMPTZ := NOW() + INTERVAL '7 days';
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.has_universe_role(p_universe_id, ARRAY['owner','admin']) THEN
    RAISE EXCEPTION 'Non autorisé';
  END IF;

  v_token := replace(gen_random_uuid()::text, '-', '');

  INSERT INTO public.universe_invites (universe_id, token, created_by, expires_at)
  VALUES (p_universe_id, v_token, auth.uid(), v_expires)
  ON CONFLICT (universe_id) DO UPDATE
    SET token      = EXCLUDED.token,
        created_by = EXCLUDED.created_by,
        created_at = NOW(),
        expires_at = EXCLUDED.expires_at;

  RETURN QUERY SELECT v_token, v_expires;
END;
$$;

GRANT EXECUTE ON FUNCTION public.generate_universe_invite(UUID) TO authenticated;

-- ══════════════════════════════════════════════════════════════
-- Aperçu d'une invitation (avant adhésion) — accessible à tout
-- utilisateur connecté, même non-membre de l'univers concerné.
-- ══════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.get_universe_invite_preview(p_token TEXT)
RETURNS TABLE(
  universe_id            UUID,
  name                   TEXT,
  description            TEXT,
  illustration_url       TEXT,
  illustration_position  INT,
  is_member              BOOLEAN,
  is_expired             BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invite RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ui.universe_id, ui.expires_at INTO v_invite
  FROM public.universe_invites ui
  WHERE ui.token = p_token;

  IF v_invite.universe_id IS NULL THEN
    RAISE EXCEPTION 'Invitation introuvable';
  END IF;

  RETURN QUERY
  SELECT u.id, u.name, u.description, u.illustration_url, u.illustration_position,
         public.is_universe_member(u.id, auth.uid()),
         (v_invite.expires_at < NOW())
  FROM public.universes u
  WHERE u.id = v_invite.universe_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.get_universe_invite_preview(TEXT) TO authenticated;

-- ══════════════════════════════════════════════════════════════
-- Acceptation d'une invitation : ajoute l'utilisateur courant comme
-- 'player' de l'univers (idempotent si déjà membre).
-- ══════════════════════════════════════════════════════════════
CREATE OR REPLACE FUNCTION public.accept_universe_invite(p_token TEXT)
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_invite RECORD;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT ui.universe_id, ui.expires_at INTO v_invite
  FROM public.universe_invites ui
  WHERE ui.token = p_token;

  IF v_invite.universe_id IS NULL THEN
    RAISE EXCEPTION 'Invitation introuvable';
  END IF;

  IF v_invite.expires_at < NOW() THEN
    RAISE EXCEPTION 'Invitation expirée';
  END IF;

  INSERT INTO public.universe_members (universe_id, user_id, role)
  VALUES (v_invite.universe_id, auth.uid(), 'player')
  ON CONFLICT (universe_id, user_id) DO NOTHING;

  RETURN v_invite.universe_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.accept_universe_invite(TEXT) TO authenticated;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Fin.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/39_universe_invite_links.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/40_chronicle_entry_likes.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Likes sur les entrées de chronique
--
-- Un utilisateur peut aimer (cœur) une entrée de chronique, une
-- seule fois par entrée. Le total des likes cumulés sur toutes les
-- entrées d'une chronique s'affiche sur son étiquette et dans sa
-- vue détail.
-- ══════════════════════════════════════════════════════════════

BEGIN;

CREATE TABLE IF NOT EXISTS public.chronicle_entry_likes (
  entry_id   UUID NOT NULL REFERENCES public.chronicle_entries(id) ON DELETE CASCADE,
  user_id    UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (entry_id, user_id)
);

CREATE INDEX IF NOT EXISTS entry_likes_entry_id_idx ON public.chronicle_entry_likes(entry_id);

ALTER TABLE public.chronicle_entry_likes ENABLE ROW LEVEL SECURITY;

-- Reprend la logique de visibilité de "entries_select" (sql/38) pour
-- déterminer qui peut voir/aimer une entrée donnée, sans dupliquer
-- l'expression dans chaque policy authenticated ci-dessous.
CREATE OR REPLACE FUNCTION public.can_view_chronicle_entry(p_entry_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
STABLE
SET search_path = public
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.chronicle_entries e
    JOIN public.chronicles c ON c.id = e.chronicle_id
    WHERE e.id = p_entry_id
      AND (
        c.user_id = auth.uid()
        OR (
          c.is_public = TRUE
          AND (
            public.has_universe_role(c.universe_id, ARRAY['owner', 'gm'])
            OR (
              public.shares_campaign_with(c.universe_id, c.user_id, auth.uid())
              AND (
                NOT public.campaign_content_restricted(c.universe_id)
                OR EXISTS (
                  SELECT 1
                  FROM public.campaign_members cm
                  JOIN public.campaigns cc ON cc.id = cm.campaign_id
                  JOIN public.campaign_visible_chronicles cvc ON cvc.campaign_id = cc.id
                  WHERE cc.universe_id = c.universe_id
                    AND cm.user_id = auth.uid()
                    AND cvc.chronicle_id = c.id
                )
              )
            )
          )
        )
      )
  );
$$;

GRANT EXECUTE ON FUNCTION public.can_view_chronicle_entry(UUID) TO authenticated;

DROP POLICY IF EXISTS "entry_likes_select" ON public.chronicle_entry_likes;
CREATE POLICY "entry_likes_select" ON public.chronicle_entry_likes FOR SELECT
  USING (public.can_view_chronicle_entry(entry_id));

-- Visiteurs anonymes : mêmes règles que "entries_select_anon", pas de
-- notion de campagne puisqu'ils ne sont membres d'aucun univers.
DROP POLICY IF EXISTS "entry_likes_select_anon" ON public.chronicle_entry_likes;
CREATE POLICY "entry_likes_select_anon" ON public.chronicle_entry_likes FOR SELECT
  TO anon
  USING (EXISTS (
    SELECT 1 FROM public.chronicle_entries e
    JOIN public.chronicles c ON c.id = e.chronicle_id
    WHERE e.id = chronicle_entry_likes.entry_id AND c.is_public = TRUE
  ));

-- On ne peut pas aimer une entrée de sa propre chronique (le like doit
-- venir d'un autre lecteur pour refléter une appréciation du groupe).
DROP POLICY IF EXISTS "entry_likes_insert" ON public.chronicle_entry_likes;
CREATE POLICY "entry_likes_insert" ON public.chronicle_entry_likes FOR INSERT
  WITH CHECK (
    auth.uid() = user_id
    AND public.can_view_chronicle_entry(entry_id)
    AND NOT EXISTS (
      SELECT 1 FROM public.chronicle_entries e
      JOIN public.chronicles c ON c.id = e.chronicle_id
      WHERE e.id = chronicle_entry_likes.entry_id AND c.user_id = auth.uid()
    )
  );

DROP POLICY IF EXISTS "entry_likes_delete" ON public.chronicle_entry_likes;
CREATE POLICY "entry_likes_delete" ON public.chronicle_entry_likes FOR DELETE
  USING (auth.uid() = user_id);

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Fin.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/40_chronicle_entry_likes.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/41_delete_universe_maps_cleanup.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : cartes oubliées à la suppression d'un univers
--
-- delete_universe() renvoie les illustration_url à nettoyer côté
-- storage (universes, characters, chronicles, documents) mais
-- oubliait les image_url de la table maps. Le nettoyage des cartes
-- reposait donc uniquement sur un sb.storage.list()+remove() côté
-- client, lancé après coup et jamais attendu (fire-and-forget) :
-- en cas d'échec réseau ou de fermeture d'onglet juste après la
-- suppression, les fichiers du bucket map-images restaient orphelins
-- sans qu'aucune erreur ne soit visible (cf. sql/28 is_orphan_illustration
-- et admin_list_orphan_illustrations qui les détectent après coup).
-- ══════════════════════════════════════════════════════════════

BEGIN;

CREATE OR REPLACE FUNCTION public.delete_universe(p_universe_id UUID)
RETURNS TEXT[]
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_owner UUID;
  v_urls  TEXT[];
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  SELECT owner_id INTO v_owner
  FROM public.universes
  WHERE id = p_universe_id;

  IF v_owner IS NULL THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  IF v_owner != auth.uid() THEN
    RAISE EXCEPTION 'Seul le propriétaire peut supprimer cet univers';
  END IF;

  -- Collecte les URLs d'illustration de tout l'univers (y compris les
  -- éléments privés créés par d'autres membres, invisibles via les
  -- policies RLS SELECT habituelles) pour nettoyage du storage côté client.
  SELECT COALESCE(array_agg(url), ARRAY[]::TEXT[]) INTO v_urls
  FROM (
    SELECT illustration_url AS url FROM public.universes  WHERE id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT (data->>'illustration_url') FROM public.characters WHERE universe_id = p_universe_id AND (data->>'illustration_url') IS NOT NULL AND (data->>'illustration_url') <> ''
    UNION ALL
    SELECT illustration_url FROM public.chronicles WHERE universe_id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT illustration_url FROM public.documents  WHERE universe_id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT image_url FROM public.maps WHERE universe_id = p_universe_id AND image_url <> ''
  ) t;

  -- SECURITY DEFINER : le cascade delete ci-dessous doit purger toutes les
  -- données de l'univers (personnages, chroniques, documents, campagnes,
  -- cartes...) même celles créées par d'autres membres, dont les policies
  -- RLS individuelles (auth.uid() = user_id) ne laisseraient pas le
  -- propriétaire de l'univers les supprimer directement.
  DELETE FROM public.universes WHERE id = p_universe_id;

  RETURN v_urls;
END;
$$;

GRANT EXECUTE ON FUNCTION public.delete_universe(UUID) TO authenticated;

-- Même correctif pour la suppression d'univers depuis le panneau admin.
CREATE OR REPLACE FUNCTION public.admin_delete_universe(p_universe_id UUID)
RETURNS TEXT[]
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_urls TEXT[];
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  IF NOT EXISTS (SELECT 1 FROM public.universes WHERE id = p_universe_id) THEN
    RAISE EXCEPTION 'Univers introuvable';
  END IF;

  SELECT COALESCE(array_agg(url), ARRAY[]::TEXT[]) INTO v_urls
  FROM (
    SELECT illustration_url AS url FROM public.universes  WHERE id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT (data->>'illustration_url') FROM public.characters WHERE universe_id = p_universe_id AND (data->>'illustration_url') IS NOT NULL AND (data->>'illustration_url') <> ''
    UNION ALL
    SELECT illustration_url FROM public.chronicles WHERE universe_id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT illustration_url FROM public.documents  WHERE universe_id = p_universe_id AND illustration_url <> ''
    UNION ALL
    SELECT image_url FROM public.maps WHERE universe_id = p_universe_id AND image_url <> ''
  ) t;

  DELETE FROM public.universes WHERE id = p_universe_id;

  RETURN v_urls;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_delete_universe(UUID) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/41_delete_universe_maps_cleanup.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/42_fix_map_images_orphan_purge_rls.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Correctif : la purge des orphelins map-images
-- échoue silencieusement pour un admin qui ne possède aucun univers
--
-- map_images_delete_orphan_by_any_owner (sql/28) exige
-- EXISTS (SELECT 1 FROM universes WHERE owner_id = auth.uid()) en plus
-- de is_orphan_illustration(). Un compte admin sans univers personnel
-- (cf. admin_users, sql/30) ne remplit jamais cette condition : la
-- suppression via l'API Storage est bloquée par RLS sans erreur
-- visible (sb.storage.remove() renvoie juste moins d'objets supprimés
-- que demandé). C'est pourquoi purgeOrphans() nettoyait bien les
-- fichiers character-illustrations (policy sans cette restriction)
-- mais laissait les fichiers map-images en place.
--
-- On ajoute is_admin() comme alternative à la propriété d'un univers,
-- sur le même principe que illustrations_delete_own côté
-- character-illustrations (is_orphan_illustration() est déjà la seule
-- garantie de sécurité nécessaire : un fichier réellement utilisé ne
-- peut jamais la valider).
-- ══════════════════════════════════════════════════════════════

BEGIN;

DROP POLICY IF EXISTS "map_images_delete_orphan_by_any_owner" ON storage.objects;
CREATE POLICY "map_images_delete_orphan_by_any_owner"
  ON storage.objects FOR DELETE
  TO authenticated
  USING (
    bucket_id = 'map-images'
    AND (
      EXISTS (SELECT 1 FROM public.universes u WHERE u.owner_id = auth.uid())
      OR public.is_admin()
    )
    AND public.is_orphan_illustration(bucket_id, name)
  );

COMMIT;

-- ==================================================
-- END sql/42_fix_map_images_orphan_purge_rls.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/43_map_marker_link_map.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Lien d'un marqueur de carte vers une AUTRE carte
-- À exécuter sur une base ayant déjà reçu sql/27_map_markers_linked_object.sql
--
-- Un marqueur de carte pouvait déjà pointer vers un personnage ou
-- un document (linked_type IN ('char','doc')). On étend la
-- contrainte pour autoriser également 'map' : un marqueur peut
-- désormais renvoyer vers une autre carte de l'univers (navigation
-- imbriquée, ex: un marqueur de ville sur la carte du monde ouvre
-- le plan détaillé de cette ville).
-- ══════════════════════════════════════════════════════════════

BEGIN;

ALTER TABLE public.map_markers
  DROP CONSTRAINT IF EXISTS map_markers_linked_type_check;

ALTER TABLE public.map_markers
  ADD CONSTRAINT map_markers_linked_type_check
  CHECK (linked_type IN ('char', 'doc', 'map'));

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Résumé :
--  • map_markers.linked_type accepte désormais 'map' en plus de
--    'char' et 'doc' (linked_id référence alors public.maps.id).
--  • La table public.maps est déjà lisible par tout membre de
--    l'univers (policy "maps_select"), donc aucune règle RLS
--    supplémentaire n'est nécessaire.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/43_map_marker_link_map.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/44_universe_owner_delete_shared_content.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply Portal — Droit de suppression MJ/propriétaire sur le
-- contenu public partagé de son univers.
--
-- Constat : les policies UPDATE de characters, chronicles,
-- chronicle_entries, documents et map_layers ont été enrichies
-- (sql/00 + migrations suivantes) pour autoriser un MJ/propriétaire
-- d'univers (can_gm_edit) à éditer un objet public appartenant à un
-- autre joueur avec qui il partage une campagne. Les policies DELETE
-- correspondantes n'ont jamais reçu la même extension et sont
-- restées strictement limitées au propriétaire de la ligne
-- (auth.uid() = user_id), ce qui empêchait un MJ/propriétaire de
-- supprimer un élément partagé qu'il pouvait pourtant éditer.
--
-- map_markers n'est pas concerné : sa policy "map_markers_all_own"
-- est déjà FOR ALL et couvre donc DELETE via can_gm_edit.
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- Personnages
DROP POLICY IF EXISTS "characters_delete" ON public.characters;
CREATE POLICY "characters_delete" ON public.characters FOR DELETE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

-- Chroniques
DROP POLICY IF EXISTS "chronicles_delete" ON public.chronicles;
CREATE POLICY "chronicles_delete" ON public.chronicles FOR DELETE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

-- Entrées de chronique
DROP POLICY IF EXISTS "entries_delete" ON public.chronicle_entries;
CREATE POLICY "entries_delete" ON public.chronicle_entries FOR DELETE
  USING (EXISTS (
    SELECT 1 FROM public.chronicles c
    WHERE c.id = chronicle_entries.chronicle_id
      AND (
        c.user_id = auth.uid()
        OR (c.is_public = TRUE AND public.can_gm_edit(c.universe_id, c.user_id, auth.uid()))
      )
  ));

-- Documents
DROP POLICY IF EXISTS "documents_delete" ON public.documents;
CREATE POLICY "documents_delete" ON public.documents FOR DELETE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

-- Couches de carte
DROP POLICY IF EXISTS "map_layers_delete" ON public.map_layers;
CREATE POLICY "map_layers_delete" ON public.map_layers FOR DELETE
  USING (
    auth.uid() = user_id
    OR (is_public = TRUE AND public.can_gm_edit(universe_id, user_id, auth.uid()))
  );

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Fin.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/44_universe_owner_delete_shared_content.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/45_whatsnew.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Nouveautés (changelog affiché à la connexion)
--
-- Ajoute une table public.news (rédigée en markdown depuis le
-- panneau d'administration) et le suivi par utilisateur de ce qui a
-- déjà été vu (profiles.last_seen_news_at). À la connexion, le client
-- appelle get_unseen_news() : toute nouveauté publiée après la
-- dernière visite est concaténée dans une modale (cf. whatsnew.js,
-- même chrome que legal.js), puis mark_news_seen() avance le curseur.
--
-- news n'a aucune policy RLS : elle n'est lisible/modifiable que via
-- les fonctions SECURITY DEFINER ci-dessous, jamais directement par
-- les clients (même pattern que admin_users, cf. 30_admin_panel.sql).
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Table des nouveautés ──────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.news (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  title                TEXT NOT NULL,
  content_markdown     TEXT NOT NULL,
  title_en             TEXT,
  content_markdown_en  TEXT,
  published_at         TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  created_by           UUID REFERENCES auth.users(id) ON DELETE SET NULL,
  created_at           TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE public.news ENABLE ROW LEVEL SECURITY;

-- Versions anglaises (optionnelles). Repli sur le français côté client
-- lorsqu'elles sont absentes.
ALTER TABLE public.news ADD COLUMN IF NOT EXISTS title_en            TEXT;
ALTER TABLE public.news ADD COLUMN IF NOT EXISTS content_markdown_en TEXT;


-- ── 2. Suivi par utilisateur ─────────────────────────────────────
-- Défaut à NOW() : un compte déjà existant au moment de la migration
-- ne se retrouve pas avec tout l'historique des nouveautés à sa
-- prochaine connexion.

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS last_seen_news_at TIMESTAMPTZ NOT NULL DEFAULT NOW();


-- ── 3. Lecture utilisateur ───────────────────────────────────────

CREATE OR REPLACE FUNCTION public.get_unseen_news()
RETURNS TABLE(id UUID, title TEXT, content_markdown TEXT, title_en TEXT, content_markdown_en TEXT, published_at TIMESTAMPTZ)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT n.id, n.title, n.content_markdown, n.title_en, n.content_markdown_en, n.published_at
  FROM public.news n
  WHERE n.published_at > (SELECT p.last_seen_news_at FROM public.profiles p WHERE p.id = auth.uid())
    AND n.published_at <= NOW()
  ORDER BY n.published_at ASC;
$$;

GRANT EXECUTE ON FUNCTION public.get_unseen_news() TO authenticated;


CREATE OR REPLACE FUNCTION public.mark_news_seen(p_up_to TIMESTAMPTZ)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  UPDATE public.profiles
  SET last_seen_news_at = p_up_to
  WHERE id = auth.uid()
    AND p_up_to > last_seen_news_at;
END;
$$;

GRANT EXECUTE ON FUNCTION public.mark_news_seen(TIMESTAMPTZ) TO authenticated;


-- ── 4. Gestion admin ──────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.admin_list_news()
RETURNS TABLE(id UUID, title TEXT, content_markdown TEXT, title_en TEXT, content_markdown_en TEXT, published_at TIMESTAMPTZ, created_at TIMESTAMPTZ)
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  RETURN QUERY
  SELECT n.id, n.title, n.content_markdown, n.title_en, n.content_markdown_en, n.published_at, n.created_at
  FROM public.news n
  ORDER BY n.published_at DESC;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_list_news() TO authenticated;


CREATE OR REPLACE FUNCTION public.admin_create_news(
  p_title              TEXT,
  p_content_markdown   TEXT,
  p_title_en           TEXT DEFAULT NULL,
  p_content_markdown_en TEXT DEFAULT NULL,
  p_published_at       TIMESTAMPTZ DEFAULT NOW())
RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_id UUID;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  INSERT INTO public.news (title, content_markdown, title_en, content_markdown_en, published_at, created_by)
  VALUES (p_title, p_content_markdown, NULLIF(p_title_en, ''), NULLIF(p_content_markdown_en, ''), p_published_at, auth.uid())
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_create_news(TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ) TO authenticated;


CREATE OR REPLACE FUNCTION public.admin_update_news(
  p_id                 UUID,
  p_title              TEXT,
  p_content_markdown   TEXT,
  p_title_en           TEXT,
  p_content_markdown_en TEXT,
  p_published_at       TIMESTAMPTZ)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  UPDATE public.news
  SET title = p_title,
      content_markdown = p_content_markdown,
      title_en = NULLIF(p_title_en, ''),
      content_markdown_en = NULLIF(p_content_markdown_en, ''),
      published_at = p_published_at
  WHERE id = p_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_update_news(UUID, TEXT, TEXT, TEXT, TEXT, TIMESTAMPTZ) TO authenticated;


CREATE OR REPLACE FUNCTION public.admin_delete_news(p_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  DELETE FROM public.news WHERE id = p_id;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_delete_news(UUID) TO authenticated;

COMMIT;

-- ══════════════════════════════════════════════════════════════
-- Fin.
-- ══════════════════════════════════════════════════════════════

-- ==================================================
-- END sql/45_whatsnew.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/46_site_info.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Page d'information (modale « À propos »)
-- À coller dans : Supabase Dashboard > SQL Editor > New query
--
-- Ajoute une table public.site_info contenant les sections fixes de
-- la modale d'information ouverte depuis l'écran de choix d'univers
-- (cf. siteinfo.js) : « Pourquoi Camply ? », « Tarifs » et
-- « Comment ça marche ». Le contenu est rédigé en markdown depuis le
-- panneau d'administration, en français avec version anglaise
-- optionnelle (repli sur le français côté client, comme les news).
--
-- site_info n'a aucune policy RLS : elle n'est lisible/modifiable que
-- via les fonctions SECURITY DEFINER ci-dessous, jamais directement
-- par les clients (même pattern que news, cf. 45_whatsnew.sql).
-- ══════════════════════════════════════════════════════════════

BEGIN;

-- ── 1. Table des sections ────────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.site_info (
  slug                 TEXT PRIMARY KEY,
  title                TEXT NOT NULL,
  content_markdown     TEXT NOT NULL DEFAULT '',
  title_en             TEXT,
  content_markdown_en  TEXT,
  sort_order           INT NOT NULL DEFAULT 0,
  updated_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_by           UUID REFERENCES auth.users(id) ON DELETE SET NULL
);

ALTER TABLE public.site_info ENABLE ROW LEVEL SECURITY;

-- Sections fixes : créées une fois, jamais ajoutées/supprimées depuis
-- le client (seul le contenu est éditable via admin_update_site_info).
INSERT INTO public.site_info (slug, title, title_en, content_markdown, sort_order) VALUES
  ('why',     'Pourquoi Camply ?',   'Why Camply?',    '*(Contenu à rédiger depuis le panneau d''administration.)*', 1),
  ('pricing', 'Tarifs',              'Pricing',        '*(Contenu à rédiger depuis le panneau d''administration.)*', 2),
  ('how',     'Comment ça marche',   'How it works',   '*(Contenu à rédiger depuis le panneau d''administration.)*', 3)
ON CONFLICT (slug) DO NOTHING;


-- ── 2. Lecture utilisateur ───────────────────────────────────────

CREATE OR REPLACE FUNCTION public.get_site_info()
RETURNS TABLE(slug TEXT, title TEXT, content_markdown TEXT, title_en TEXT, content_markdown_en TEXT, sort_order INT)
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT s.slug, s.title, s.content_markdown, s.title_en, s.content_markdown_en, s.sort_order
  FROM public.site_info s
  ORDER BY s.sort_order ASC;
$$;

GRANT EXECUTE ON FUNCTION public.get_site_info() TO authenticated;


-- ── 3. Édition admin ─────────────────────────────────────────────

CREATE OR REPLACE FUNCTION public.admin_update_site_info(
  p_slug                TEXT,
  p_title               TEXT,
  p_content_markdown    TEXT,
  p_title_en            TEXT,
  p_content_markdown_en TEXT)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  UPDATE public.site_info
  SET title = p_title,
      content_markdown = p_content_markdown,
      title_en = NULLIF(p_title_en, ''),
      content_markdown_en = NULLIF(p_content_markdown_en, ''),
      updated_at = NOW(),
      updated_by = auth.uid()
  WHERE slug = p_slug;
END;
$$;

GRANT EXECUTE ON FUNCTION public.admin_update_site_info(TEXT, TEXT, TEXT, TEXT, TEXT) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/46_site_info.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/47_universe_search.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Recherche full-text dans un univers
--
-- Fonction RPC unique `search_universe(universe, query)` qui cherche un
-- ou plusieurs mots à travers les éléments d'un univers (personnages,
-- chroniques, entrées de chronique, documents, marqueurs de carte) et
-- renvoie de quoi naviguer vers chaque résultat.
-- Bilingue (french + english). SECURITY INVOKER → la RLS s'applique,
-- donc seul le contenu lisible par l'appelant est renvoyé.
-- ══════════════════════════════════════════════════════════════

BEGIN;

DROP FUNCTION IF EXISTS public.search_universe(uuid, text);

CREATE OR REPLACE FUNCTION public.search_universe(
  p_universe_id uuid,
  p_query       text
)
RETURNS TABLE (
  kind      text,   -- 'char' | 'chr' | 'entry' | 'doc' | 'marker'
  id        uuid,   -- cible passée à navigateToXxx() ; pour 'marker' = id de la carte
  parent_id uuid,   -- 'entry' → id de la chronique parente ; sinon NULL
  title     text,
  snippet   text,   -- extrait surligné via les jetons @@HL@@ … @@/HL@@
  score     real
)
LANGUAGE plpgsql
SECURITY INVOKER
STABLE
SET search_path = public
AS $$
DECLARE
  q_fr   tsquery;
  q_en   tsquery;
  v_opts text := 'StartSel="@@HL@@", StopSel="@@/HL@@", MaxFragments=1, MaxWords=24, MinWords=8, ShortWord=2, HighlightAll=FALSE';
BEGIN
  -- Réservé aux membres de l'univers.
  IF NOT public.is_universe_member(p_universe_id, auth.uid()) THEN
    RETURN;
  END IF;

  p_query := btrim(coalesce(p_query, ''));
  IF length(p_query) < 2 THEN
    RETURN;
  END IF;

  q_fr := websearch_to_tsquery('french',  p_query);
  q_en := websearch_to_tsquery('english', p_query);

  -- Requête vide (uniquement des mots vides / de la ponctuation) → rien.
  IF numnode(q_fr) = 0 AND numnode(q_en) = 0 THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT
    b.kind,
    b.id,
    b.parent_id,
    b.title,
    CASE
      WHEN to_tsvector('french', b.doc) @@ q_fr
        THEN ts_headline('french',  coalesce(nullif(b.src, ''), b.title), q_fr, v_opts)
      ELSE   ts_headline('english', coalesce(nullif(b.src, ''), b.title), q_en, v_opts)
    END AS snippet,
    greatest(
      ts_rank(to_tsvector('french',  b.doc), q_fr),
      ts_rank(to_tsvector('english', b.doc), q_en)
    ) AS score
  FROM (
    -- ── Personnages ──────────────────────────────────────────
    SELECT
      'char'::text AS kind,
      c.id         AS id,
      NULL::uuid   AS parent_id,
      c.name       AS title,
      concat_ws(' ',
        c.name,
        c.data->>'subtitle',
        c.data->>'race',
        c.data->>'class',
        c.data->>'description',
        c.data->>'background',
        (SELECT string_agg(concat_ws(' ', tr->>'name', tr->>'detail'), ' ')
           FROM jsonb_array_elements(coalesce(c.data->'traits', '[]'::jsonb)) AS tr),
        (SELECT string_agg(sk->>'name', ' ')
           FROM jsonb_array_elements(coalesce(c.data->'skills', '[]'::jsonb)) AS sk),
        (SELECT string_agg(concat_ws(' ', ch->>'name', ch->>'trigram'), ' ')
           FROM jsonb_array_elements(coalesce(c.data->'characteristics', '[]'::jsonb)) AS ch)
      ) AS doc,
      concat_ws('. ',
        c.data->>'description',
        c.data->>'background',
        (SELECT string_agg(concat_ws(' : ', tr->>'name', tr->>'detail'), '. ')
           FROM jsonb_array_elements(coalesce(c.data->'traits', '[]'::jsonb)) AS tr)
      ) AS src
    FROM public.characters c
    WHERE c.universe_id = p_universe_id

    UNION ALL

    -- ── Chroniques ───────────────────────────────────────────
    SELECT
      'chr'::text,
      ch.id,
      NULL::uuid,
      ch.title,
      concat_ws(' ', ch.title, ch.description),
      ch.description
    FROM public.chronicles ch
    WHERE ch.universe_id = p_universe_id

    UNION ALL

    -- ── Entrées de chronique ─────────────────────────────────
    -- (chronicle_entries n'a pas d'universe_id : on passe par la chronique)
    SELECT
      'entry'::text,
      e.id,
      e.chronicle_id,
      e.title,
      concat_ws(' ', e.title, e.content),
      e.content
    FROM public.chronicle_entries e
    JOIN public.chronicles ch2 ON ch2.id = e.chronicle_id
    WHERE ch2.universe_id = p_universe_id

    UNION ALL

    -- ── Documents ────────────────────────────────────────────
    SELECT
      'doc'::text,
      d.id,
      NULL::uuid,
      d.title,
      concat_ws(' ', d.title, d.content),
      d.content
    FROM public.documents d
    WHERE d.universe_id = p_universe_id

    UNION ALL

    -- ── Marqueurs de carte ───────────────────────────────────
    -- Le résultat pointe vers la carte (maps.id) qui contient le marqueur,
    -- reliée via (universe_id, map_key).
    SELECT
      'marker'::text,
      m.id,                       -- id de la carte, attendu par navigateToMap()
      NULL::uuid,
      mk.name,
      concat_ws(' ', mk.name, mk.description),
      mk.description
    FROM public.map_markers mk
    JOIN public.maps m
      ON m.universe_id = mk.universe_id
     AND m.map_key     = mk.map_key
    WHERE mk.universe_id = p_universe_id
  ) AS b
  WHERE to_tsvector('french',  b.doc) @@ q_fr
     OR to_tsvector('english', b.doc) @@ q_en
  ORDER BY score DESC, b.title ASC
  LIMIT 60;
END;
$$;

GRANT EXECUTE ON FUNCTION public.search_universe(uuid, text) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/47_universe_search.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/48_universe_members_list.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- CAMPLY — Liste des membres d'un univers en un seul aller-retour
--
-- `get_universe_members` joint universe_members et profiles côté base afin
-- que l'onglet Configuration n'ait plus besoin de deux requêtes enchaînées
-- (membres, puis pseudos) avant son premier rendu.
--
-- Sécurité : SECURITY INVOKER → la RLS s'applique normalement
-- (universe_members_select_same_universe pour l'appartenance,
-- profiles_select_public pour le pseudo). Un garde `is_universe_member`
-- coupe court si l'appelant n'appartient pas à l'univers.
-- ══════════════════════════════════════════════════════════════

BEGIN;

DROP FUNCTION IF EXISTS public.get_universe_members(uuid);

CREATE OR REPLACE FUNCTION public.get_universe_members(p_universe_id uuid)
RETURNS TABLE (
  user_id   uuid,
  role      text,
  joined_at timestamptz,
  username  text
)
LANGUAGE sql
SECURITY INVOKER
STABLE
SET search_path = public
AS $$
  SELECT m.user_id,
         m.role,
         m.joined_at,
         COALESCE(p.username, '?') AS username
  FROM public.universe_members m
  LEFT JOIN public.profiles p ON p.id = m.user_id
  WHERE m.universe_id = p_universe_id
    AND public.is_universe_member(p_universe_id, auth.uid())
  ORDER BY m.joined_at ASC;
$$;

GRANT EXECUTE ON FUNCTION public.get_universe_members(uuid) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/48_universe_members_list.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/49_campaign_export_scope.sql
-- ==================================================
-- ═══════════════════════════════════════════════════════════════════
-- CAMPLY — Périmètre d'export d'une campagne
--
-- Retourne les identifiants des objets explicitement attachés à une
-- campagne et encore visibles pour l'appelant. Les jointures vers les
-- tables de contenu sont volontaires : avec SECURITY INVOKER, leurs
-- policies RLS éliminent les objets auxquels l'utilisateur n'a plus accès.
--
-- Le garde sur campaigns vérifie également que la campagne appartient à
-- l'univers demandé et que l'appelant est membre de la campagne, owner ou
-- MJ de l'univers.
-- ═══════════════════════════════════════════════════════════════════

BEGIN;

DROP FUNCTION IF EXISTS public.get_campaign_export_scope(uuid, uuid);

CREATE OR REPLACE FUNCTION public.get_campaign_export_scope(
  p_universe_id uuid,
  p_campaign_id uuid
)
RETURNS TABLE (
  object_type text,
  object_id   uuid
)
LANGUAGE sql
SECURITY INVOKER
STABLE
SET search_path = public
AS $$
  WITH requested_campaign AS (
    SELECT c.id
    FROM public.campaigns c
    WHERE c.id = p_campaign_id
      AND c.universe_id = p_universe_id
      AND (
        public.is_campaign_member(c.id, auth.uid())
        OR public.has_universe_role(c.universe_id, ARRAY['owner', 'gm'], auth.uid())
      )
  )
  SELECT 'character'::text, cvc.character_id
  FROM requested_campaign rc
  JOIN public.campaign_visible_characters cvc ON cvc.campaign_id = rc.id
  JOIN public.characters ch ON ch.id = cvc.character_id
  WHERE ch.universe_id = p_universe_id

  UNION ALL

  SELECT 'chronicle'::text, cvc.chronicle_id
  FROM requested_campaign rc
  JOIN public.campaign_visible_chronicles cvc ON cvc.campaign_id = rc.id
  JOIN public.chronicles ch ON ch.id = cvc.chronicle_id
  WHERE ch.universe_id = p_universe_id

  UNION ALL

  SELECT 'document'::text, cvd.document_id
  FROM requested_campaign rc
  JOIN public.campaign_visible_documents cvd ON cvd.campaign_id = rc.id
  JOIN public.documents d ON d.id = cvd.document_id
  WHERE d.universe_id = p_universe_id

  UNION ALL

  SELECT 'map'::text, cvm.map_layer_id
  FROM requested_campaign rc
  JOIN public.campaign_visible_maps cvm ON cvm.campaign_id = rc.id
  JOIN public.map_layers ml ON ml.id = cvm.map_layer_id
  WHERE ml.universe_id = p_universe_id;
$$;

REVOKE ALL ON FUNCTION public.get_campaign_export_scope(uuid, uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_campaign_export_scope(uuid, uuid) TO authenticated;

COMMIT;

-- ==================================================
-- END sql/49_campaign_export_scope.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/50_admin_user_status.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Statut d'activité dans la liste des utilisateurs admin
--
-- Un compte est considéré actif s'il s'est connecté au moins une fois
-- au cours des 30 derniers jours, comme dans admin_get_stats().
-- ══════════════════════════════════════════════════════════════

BEGIN;

DROP FUNCTION IF EXISTS public.admin_list_users();

CREATE FUNCTION public.admin_list_users()
RETURNS TABLE(
  user_id         UUID,
  username        TEXT,
  email           TEXT,
  max_universes   INT,
  owned_universes BIGINT,
  objects_count   BIGINT,
  created_at      TIMESTAMPTZ,
  is_active       BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.username,
    au.email::text,
    p.max_universes,
    COALESCE(uc.owned_count, 0),
    COALESCE(oc.total, 0),
    au.created_at,
    COALESCE(au.last_sign_in_at >= now() - interval '30 days', FALSE)
  FROM public.profiles p
  JOIN auth.users au ON au.id = p.id
  LEFT JOIN (
    SELECT un.owner_id AS oid, count(*) AS owned_count
    FROM public.universes un
    GROUP BY un.owner_id
  ) uc ON uc.oid = p.id
  LEFT JOIN (
    SELECT t.uid, count(*) AS total FROM (
      SELECT c.user_id  AS uid FROM public.characters c
      UNION ALL SELECT ch.user_id AS uid FROM public.chronicles ch
      UNION ALL SELECT d.user_id  AS uid FROM public.documents d
      UNION ALL SELECT cp.user_id AS uid FROM public.campaigns cp
      UNION ALL SELECT m.created_by AS uid FROM public.maps m
    ) t
    GROUP BY t.uid
  ) oc ON oc.uid = p.id
  ORDER BY au.created_at;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.admin_list_users() FROM PUBLIC;
REVOKE EXECUTE ON FUNCTION public.admin_list_users() FROM anon;
GRANT EXECUTE ON FUNCTION public.admin_list_users() TO authenticated;

COMMIT;

-- ==================================================
-- END sql/50_admin_user_status.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/51_user_last_seen.sql
-- ==================================================
-- ══════════════════════════════════════════════════════════════
-- Camply — Suivi de la dernière visite d'un utilisateur
--
-- profiles.last_seen_at enregistre chaque chargement authentifié de
-- Camply. Pour les comptes qui n'ont pas encore revisité le site après
-- cette migration, les indicateurs admin se replient temporairement sur
-- auth.users.last_sign_in_at.
-- ══════════════════════════════════════════════════════════════

BEGIN;

ALTER TABLE public.profiles
  ADD COLUMN IF NOT EXISTS last_seen_at TIMESTAMPTZ;

COMMENT ON COLUMN public.profiles.last_seen_at IS
  'Dernier chargement authentifié de Camply pour cet utilisateur.';

CREATE OR REPLACE FUNCTION public.touch_user_visit(p_username TEXT)
RETURNS TIMESTAMPTZ
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_seen_at TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  INSERT INTO public.profiles (id, username, last_seen_at)
  VALUES (auth.uid(), p_username, v_seen_at)
  ON CONFLICT (id) DO UPDATE
  SET username = EXCLUDED.username,
      last_seen_at = EXCLUDED.last_seen_at;

  RETURN v_seen_at;
END;
$$;

REVOKE ALL ON FUNCTION public.touch_user_visit(TEXT) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.touch_user_visit(TEXT) TO authenticated;

REVOKE SELECT, INSERT, UPDATE, DELETE ON public.profiles FROM anon, authenticated;
GRANT SELECT (id, username) ON public.profiles TO anon;
GRANT SELECT (id, username, max_universes) ON public.profiles TO authenticated;

CREATE OR REPLACE FUNCTION public.admin_get_stats()
RETURNS JSONB
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_characters       BIGINT;
  v_chronicles       BIGINT;
  v_documents        BIGINT;
  v_campaigns        BIGINT;
  v_maps             BIGINT;
  v_universes_active BIGINT;
  v_universes_paused BIGINT;
  v_storage_bytes    BIGINT;
  v_db_bytes         BIGINT;
  v_orphan_count     BIGINT;
  v_orphan_bytes     BIGINT;
  v_users_total      BIGINT;
  v_users_active     BIGINT;
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  SELECT count(*) INTO v_characters FROM public.characters;
  SELECT count(*) INTO v_chronicles FROM public.chronicles;
  SELECT count(*) INTO v_documents  FROM public.documents;
  SELECT count(*) INTO v_campaigns  FROM public.campaigns;
  SELECT count(*) INTO v_maps       FROM public.maps;

  SELECT count(*) FILTER (WHERE paused_at IS NULL),
         count(*) FILTER (WHERE paused_at IS NOT NULL)
    INTO v_universes_active, v_universes_paused
    FROM public.universes;

  SELECT count(*),
         count(*) FILTER (
           WHERE COALESCE(p.last_seen_at, au.last_sign_in_at) >= now() - interval '30 days'
         )
    INTO v_users_total, v_users_active
    FROM auth.users au
    LEFT JOIN public.profiles p ON p.id = au.id;

  SELECT COALESCE(SUM((o.metadata->>'size')::bigint), 0) INTO v_storage_bytes
  FROM storage.objects o;

  SELECT pg_database_size(current_database()) INTO v_db_bytes;

  SELECT count(*), COALESCE(SUM((o.metadata->>'size')::bigint), 0)
    INTO v_orphan_count, v_orphan_bytes
    FROM storage.objects o
    WHERE o.bucket_id IN ('character-illustrations', 'map-images')
      AND public.is_orphan_illustration(o.bucket_id, o.name);

  RETURN jsonb_build_object(
    'objects', jsonb_build_object(
      'characters', v_characters,
      'chronicles', v_chronicles,
      'documents',  v_documents,
      'campaigns',  v_campaigns,
      'maps',       v_maps,
      'total',      v_characters + v_chronicles + v_documents + v_campaigns + v_maps
    ),
    'universes', jsonb_build_object(
      'active', v_universes_active,
      'paused', v_universes_paused,
      'total',  v_universes_active + v_universes_paused
    ),
    'users', jsonb_build_object(
      'total',      v_users_total,
      'active_30d', v_users_active
    ),
    'orphans', jsonb_build_object(
      'count', v_orphan_count,
      'bytes', v_orphan_bytes
    ),
    'storage', jsonb_build_object(
      'bytes',       v_storage_bytes,
      'limit_bytes', 1073741824
    ),
    'database', jsonb_build_object(
      'bytes',       v_db_bytes,
      'limit_bytes', 524288000
    )
  );
END;
$$;

REVOKE EXECUTE ON FUNCTION public.admin_get_stats() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_get_stats() TO authenticated;

DROP FUNCTION IF EXISTS public.admin_list_users();

CREATE FUNCTION public.admin_list_users()
RETURNS TABLE(
  user_id         UUID,
  username        TEXT,
  email           TEXT,
  max_universes   INT,
  owned_universes BIGINT,
  objects_count   BIGINT,
  created_at      TIMESTAMPTZ,
  last_seen_at    TIMESTAMPTZ,
  is_active       BOOLEAN
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'Accès réservé aux administrateurs';
  END IF;

  RETURN QUERY
  SELECT
    p.id,
    p.username,
    au.email::text,
    p.max_universes,
    COALESCE(uc.owned_count, 0),
    COALESCE(oc.total, 0),
    au.created_at,
    p.last_seen_at,
    COALESCE(
      COALESCE(p.last_seen_at, au.last_sign_in_at) >= now() - interval '30 days',
      FALSE
    )
  FROM public.profiles p
  JOIN auth.users au ON au.id = p.id
  LEFT JOIN (
    SELECT un.owner_id AS oid, count(*) AS owned_count
    FROM public.universes un
    GROUP BY un.owner_id
  ) uc ON uc.oid = p.id
  LEFT JOIN (
    SELECT t.uid, count(*) AS total FROM (
      SELECT c.user_id  AS uid FROM public.characters c
      UNION ALL SELECT ch.user_id AS uid FROM public.chronicles ch
      UNION ALL SELECT d.user_id  AS uid FROM public.documents d
      UNION ALL SELECT cp.user_id AS uid FROM public.campaigns cp
      UNION ALL SELECT m.created_by AS uid FROM public.maps m
    ) t
    GROUP BY t.uid
  ) oc ON oc.uid = p.id
  ORDER BY au.created_at;
END;
$$;

REVOKE EXECUTE ON FUNCTION public.admin_list_users() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_list_users() TO authenticated;

COMMIT;

-- ==================================================
-- END sql/51_user_last_seen.sql
-- ==================================================

-- ==================================================
-- BEGIN sql/52_user_activity_reliability.sql
-- ==================================================
-- =============================================================
-- Camply — Fiabilisation du suivi d'activité utilisateur
-- À exécuter après sql/51_user_last_seen.sql.
--
-- 1. Rattrape l'historique disponible dans Auth (connexion + session).
-- 2. Les anciens clients qui ouvrent un univers mettent aussi à jour
--    profiles.last_seen_at, sans dépendre du nouveau JavaScript.
-- 3. Le panneau admin utilise ensuite exclusivement last_seen_at.
-- =============================================================

BEGIN;


-- Rattrapage ponctuel : on conserve la date la plus récente connue.
-- auth.sessions n'est volontairement utilisée qu'ici, lors de la migration ;
-- le suivi courant repose ensuite sur les RPC applicatives.
WITH auth_activity AS (
  SELECT
    au.id,
    NULLIF(
      GREATEST(
        COALESCE(au.last_sign_in_at, '-infinity'::timestamptz),
        COALESCE(MAX(s.updated_at), '-infinity'::timestamptz)
      ),
      '-infinity'::timestamptz
    ) AS seen_at
  FROM auth.users au
  LEFT JOIN auth.sessions s ON s.user_id = au.id
  GROUP BY au.id, au.last_sign_in_at
)
UPDATE public.profiles p
SET last_seen_at = CASE
  WHEN p.last_seen_at IS NULL THEN a.seen_at
  ELSE GREATEST(p.last_seen_at, a.seen_at)
END
FROM auth_activity a
WHERE a.id = p.id
  AND a.seen_at IS NOT NULL
  AND (p.last_seen_at IS NULL OR p.last_seen_at < a.seen_at);


CREATE OR REPLACE FUNCTION public.touch_universe_visit(p_universe_id UUID)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = ''
AS $$
DECLARE
  v_seen_at TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Authentication required';
  END IF;

  IF NOT public.is_universe_member(p_universe_id, auth.uid()) THEN
    RAISE EXCEPTION 'Seuls les membres de l''univers peuvent enregistrer une visite';
  END IF;

  UPDATE public.universes
  SET last_visited_at = v_seen_at
  WHERE id = p_universe_id;

  UPDATE public.profiles
  SET last_seen_at = v_seen_at
  WHERE id = auth.uid();
END;
$$;

REVOKE ALL ON FUNCTION public.touch_universe_visit(UUID) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.touch_universe_visit(UUID) TO authenticated;


